/*
# SimpleLayout — stack children along an axis

The stacking idiom: siblings placed one after another along
`axis`, in child order, `spacing` apart (negative overlaps). The cross axis
and all sizes stay the children's own — a child centers itself across a row
with the ordinary `y = center`. Invisible children are skipped and their
space reclaimed; a skipped child still gets the slot it would occupy, so
re-showing it needs no special case. A `Spacer` child flexes to absorb the
run's slack along the axis (between two groups it pushes them apart; one on
each side centers the run).

Written in Declare over the Layout kernel: the whole strategy is this one
pure place() — one box per laid child, aligned by index.
*/

class SimpleLayout extends Layout [
    axis: Axis = y,
    spacing: number = 0,

    place() {
        const axis = this.axis
        const size = axis == "x" ? "width" : "height"
        const kids = this.laid()
        const flexing = (c) => (c).flexes === true

        // slack, only when someone flexes: the view's extent along the axis
        // minus the rigid content and the gaps between visible children
        let each = 0
        let flexN = 0
        for (const c of kids) if (c.visible && flexing(c)) flexN = flexN + 1
        if (flexN > 0) {
            let content = 0
            let visN = 0
            for (const c of kids) {
                if (!c.visible) continue
                visN = visN + 1
                if (!flexing(c)) content = content + (c)[size]
            }
            const extent = this.view == null ? 0 : (this.view)[size]
            each = Math.max(0, (extent - content - this.spacing * Math.max(0, visN - 1)) / flexN)
        }

        let pos = 0
        return kids.map((c) => {
            const flex = c.visible && flexing(c)
            const box = (axis == "x" ? ({ x: pos }) : ({ y: pos }))
            if (flex) box[axis == "x" ? "w" : "h"] = each
            if (c.visible) pos = pos + (flex ? each : (c)[size]) + this.spacing
            return box
            })
        }
    ]

/*
# Control

The interaction-state base every stateful control extends (docs/system-design/components-baseline.md,
Contract 3). It owns how the pointer, keyboard, and focus relate to this view — and
nothing semantic: `checked`, `value`, and their kin live on the concrete control.

The pointer half is the language's now: `hovered` and `pressed` are View's read-only
interaction intrinsics (chain-based, touch-correct, cancel-safe). What Control adds is
the CONTROL policy on top of them, as derivations every concrete control reads:

- `hot` / `down` — the styling pair: the intrinsics gated by `disabled`, with the
  keyboard-activation `flash` folded into `down`. Style against these, not the raw
  intrinsics, and a disabled control never lights up.
- `disabled` — inert: not focusable, no activation; concrete controls gate on it.
- keyboard — Space or Enter on the focused control activates it, the same `press()`
  path a pointer uses, acknowledged by flashing the pressed look.

It also owns the two things every labelled control was improvising:

- `iconLeft` / `iconRight` — decoration, by class name. A concrete control lays
  them out; Control only declares that they exist, so `Button` and `Segment`
  answer to one vocabulary.
- `menu` — the ROLE of dropping a menu. Not decoration: fifteen sites across the
  corpus call `someMenu.openFor(control)`, and the disclosure mark for that one
  role was drawn five different ways or omitted (a glyph inside the label string
  in five places, a private chevron in two, a separate `Text` in one, nothing in
  `MenuBar` and `DataGrid`). Nobody chose those differences. Setting `menu` gets
  the mark, the anchored open, the held-open styling, and Down-to-open together,
  which is the part a hand-rolled copy gets wrong one piece at a time.
*/

class Control extends View [
    disabled: boolean = false,
    focused:  boolean = false,

    // A control is chrome, not prose: its label never selects, even inside a
    // `selectable` region (a provision here vetoes the inherited value — the
    // language rule: anything that activates declares itself unselectable).

    selectable = false,

    // the styling pair — the interaction intrinsics under CONTROL policy

    hot:  boolean = { this.hovered && !this.disabled },
    down: boolean = { (this.pressed && !this.disabled) || this.flash },

    // The :focus-visible channel for the control's OWN styling (a Tab header's
    // focus edge): focused AND the focus arrived by keyboard. Captured at the
    // focus event (the web's rule), cleared by blur — and by a pointer press on
    // this very control, the one case with no focus event (Focus.focus on the
    // already-focused target is a no-op, but the modality still cleared).

    focusVisible: boolean = false,

    focusable = { !this.disabled },

    // The keyboard affordance is the app-level FocusRing (focusring.declare —
    // one traveling indicator, declared once in the App), not a per-control
    // ring; `focused` stays declared here for controls' own styling.

    // ── content slots ──────────────────────────────────────────────────────
    //
    // Icons by CLASS NAME, resolved through the tag registry. A name rather than
    // a child because a control is a leaf — everything else about it is an
    // attribute — and because an attribute is the one form where authored and
    // bound are the same mechanism: `iconLeft = TrashIcon` and
    // `iconLeft = { "" + :icon }` in a replicated toolbar are one slot.

    iconLeft:  string = "",
    iconRight: string = "",

    // The menu this control drops. Set it and the disclosure mark, the anchored
    // open, and the open-state styling all follow; `openMenu()` is the seam a
    // concrete control calls from its own `press()`.

    menu: View = null,

    // DERIVED, not written. A flag set on open goes stale the moment the menu
    // closes some other way — Escape, a pick, a click on the backdrop — and the
    // button keeps its held-open fill for the rest of the session. Reading the
    // menu's own state cannot drift: it is open if the menu is shown AND this
    // control is what opened it (one menu serves many openers).

    menuOpen: boolean = { this.menu != null
                       && (this.menu).shown === true
                       && (this.menu).opener === this },

    // What a control SHOWS on the right: an explicit icon wins, else the
    // disclosure chevron a `menu` implies. One place decides, so the five
    // improvised indicators become one.

    rightIcon: string = { this.iconRight != "" ? this.iconRight : this.menu != null ? "ChevronIcon" : "" },

    openMenu() {
        if (this.menu == null || this.disabled) return
        ;(this.menu).openFor(this)
        },

    // the activation seam — concrete controls override; pointer and keyboard both land here

    press() { if (this.menu != null) this.openMenu() },

    // the control's FOCUS SILHOUETTE — override to ring something other than
    // the whole bounds (a Radio rings its dot). null = bounds + cornerRadius.
    // { x, y, w, h, rad } in the control's own coordinates.

    focusShape() { return null },

    // keyboard activation's visual acknowledgment: flash the pressed look
    // (the platform convention for buttons — and menu items, later). Value
    // controls whose state change IS the feedback (Checkbox, Switch, Radio)
    // don't call this. `flashMs` is per-control tunable. `flash` is the
    // control's OWN state — the `pressed` intrinsic is the pointer's truth and
    // is read-only; a keyboard pulse is a different fact, folded into `down`.

    flash:   boolean = false,
    flashMs: number  = 220,

    flashPress() {
        this.flash = true
        setTimeout(() => { this.flash = false }, this.flashMs)
        },

    onFocus() { this.focused = true; this.focusVisible = Focus.byKeyboard() },
    onBlur()  { this.focused = false; this.focusVisible = false },

    // a click is also a focus claim — the keyboard picks up where the pointer left

    // A MENU opens here, not from `onClick`. Every other control routes the
    // pointer through `press()` (`onClick() { if (!disabled) press() }`), but
    // Button inverts that — its `onClick` is the USE SITE's action slot — so a
    // menu hung off `press()` opened from the keyboard and never from a click.
    // Pointer-down is also what the platform does: menus open on press, not
    // release. The keyboard keeps its own path through `press()`, and the two
    // cannot double-fire because a key press raises no pointer event.

    onPointerDown() {
        if (this.disabled) return
        this.focusVisible = false
        Focus.focus(this)
        if (this.menu != null) this.openMenu()
        },

    // Down opens a menu control — the platform convention, and the reason `menu`
    // is a role rather than an icon: an author who wired a chevron by hand never
    // got this.

    onKeyDown(e: KeyEvent) {
        if (this.disabled || e.repeat) return
        if (e.key == "Enter" || e.key == " ") this.press()
        else if (e.key == "ArrowDown" && this.menu != null) this.openMenu()
        }
    ]

/*
# Icon — the drawn mark

A small monochrome mark, **drawn** rather than typed. Fonts are not UI objects:
their glyphs are not guaranteed to be present, they rasterize differently on
every platform, and the ones that exist are the wrong shapes — a `✓` sits on the
text baseline and reads like a square-root sign, not like a checkmark. The house
already knew this in three places before it had a name for it (`Checkbox.mark`,
`Menu.check`, `Combobox.disc` are all drawn); this is that decision, stated once.

## Writing one

Subclass and override `draw`. Author the shape in a **16×16 box** — `unit`
converts it to whatever size the host asked for:

```declare-fragment
class SparkIcon extends Icon [
    draw(d: Draw) {
        d.scale(unit, unit)
        d.strokeStyle = ink; d.lineWidth = weight / unit
        d.beginPath(); d.moveTo(8, 1); d.lineTo(8, 15); d.stroke()
        }
    ]
```

Overriding a **method** is the refinement path that works — re-opening an
inherited child is not (`cap:` on a `Button` subclass fails at instantiate), so
the shape lives in `draw` and everything adjustable is a slot.

## Size changes the drawing, not the shape

Every icon is ONE path. There are no per-size variants, no thresholds, nothing
redrawn at a breakpoint: `unit` scales the 16-box to whatever the host asked for,
so a 64px icon is the 16px icon at 4×, exactly.

The **stroke** is the deliberate exception. `d.lineWidth = weight / unit` sits
*inside* `d.scale(unit, unit)`, so the two cancel and the line lands at a constant
`weight` in **device pixels at every size**. An icon's line therefore matches the
1px rules and text weights it sits among, instead of fattening as it grows.

The cost is that the stroke-to-size ratio falls: 1.6px is 10% of a 16px icon, 5%
at 32, 2.5% at 64. Across 14–18px, which is every site in this corpus, that is
invisible. Past ~32 an icon starts reading as a fine-line drawing rather than a
mark — so **this set is built for chrome sizes**, and a large display icon (an
empty-state mark, an about-box graphic) would want the opposite: `d.lineWidth =
weight` *outside* the scale, so the line grows with the drawing. Real icon
systems take a third road and redraw per optical size range; that is a bigger
undertaking than this set needs.

`test/probe/iconbook.declare` shows the ramp — the same chevron and bulb at 16,
24, 32, 48 and 64 — if the tradeoff ever needs re-judging.

## What is NOT an Icon

Application art. The desktop's dock icons are the case to look at before
reaching for this class: they rest at 56px and grow under the magnification
swell, they are polychrome (`gradient(hue1, hue2)` behind a hue-parameterised
drawing), and their **width animates every frame**. Each of those alone rules
them out — the constant stroke that suits a 16px mark is 2.9% of a 56px one and
reads spindly; `ink` is a single colour; and an animated width is the one thing
this set forbids.

The line is not "drawn versus not drawn" — dock art is drawn too. It is
**chrome vocabulary versus identity**. A mark that says *close*, *expand*,
*checked*, *this is the dark theme* belongs here, at a size the host states.
A mark that says *this is Calendar* does not, and belongs to the app that owns
the identity.

Desktop has both, which is what makes it the clarifying example: its menu rows
take `WindowIcon` and `CodeIcon` from this set, while its dock keeps `DockIcon`.

## Two rules

**Scale inside the body, never with the View's `scale`.** A recording rasterizes
into a canvas sized to its own ink bounds at device resolution
(`dom-backend.ts` `rasterize()`), while `scale` is a CSS transform applied
*after* — so `scale = { width / 16 }` would rasterize 16 pixels and stretch them.
Crisp at exactly 16, soft at every other size, which is most of them. Scaling
inside the recording allocates the raster at true size instead.

**Never animate an icon's `width`.** Reading size inside `draw` makes the
recording size-dependent: an animated size re-records AND reallocates the backing
canvas every frame, which is what dragged the dock's magnification from 60 to
~25fps (`adaptive-draw-cache.md`). A static size re-records once and costs
nothing after. Measured: 120 icons re-recording their *content* every frame runs
frame-bound at 16.6ms, cheaper than the 120 text glyphs they replace.

Colour is not a rule — `ink` follows the prevailing text colour, so an icon beside
a muted label goes muted on its own, and a host that needs a different ink (a
menu row's check inverting on the hot row) simply sets it.
*/

/* ## IconHost — a named icon, materialized

   A control names its icon (`iconLeft = TrashIcon`) rather than nesting one,
   because a control is a leaf and everything else about it is an attribute — and
   because an attribute is the one form where AUTHORED and BOUND are the same
   mechanism. `IconHost` is what turns that name into a live view, through the
   same `app.createView` seam the menu's `iconKind` already uses.

   It reserves no space when empty, so a control's `contentWidth` measures only
   the slots that are actually filled and an icon-less button needs no special
   case.

   LIMITATION, deliberate for now: the name is consumed once, at construction.
   A control whose icon must CHANGE at runtime (a play/pause toggle) is not
   served by this yet — that needs a name-valued slot the runtime re-materializes
   on change, which is a runtime feature, not a library one. Every site in this
   corpus names its icon statically. */

class IconHost extends View [
    kind: string = "",
    width  = { classroot.kind == "" ? 0 : this.iconSize },
    height = { this.iconSize },
    y = center,
    visible = { classroot.kind != "" },

    // THE INK CHANNEL. `createView` cannot pass attributes, so the only way to
    // reach the icon it builds is a PREVAILING slot — and the one `Icon.ink`
    // reads is `textColor`. Publishing it here is what lets a host state its
    // ink at all.
    //
    // The default matters more than it looks: prevailing `textColor` falls back
    // to 0x000000 platform-wide, so an icon that inherited it rendered BLACK —
    // fine on a light surface by luck, invisible on a dark one. Every
    // host-created icon in the corpus was doing that. `theme.text` is a floor
    // that is never invisible in either palette.

    ink: Color = { this.theme.text },
    textColor = { classroot.ink },

    onInit() { if (this.kind != "") this.root.createView(this.kind, this, ({ })) }
    ]


class Icon extends View [
    // The marker a layout keys on, so a control can place its icon without
    // caring which shape it is (the Segment/Segmented discipline).

    isIcon: boolean = true,

    // Size comes from the CONTEXT: `iconSize` is prevailing, so a menu states 16
    // once and every icon in every row answers. A use site may override it.

    width  = { this.iconSize },
    height = { this.width },
    y = center,

    // Follows the PREVAILING text colour, so an icon beside a muted label goes
    // muted on its own. The trap: that slot falls back to 0x000000 platform-wide,
    // so an icon in a context which never states a text colour renders BLACK and
    // disappears on a dark surface. State `ink` unless you know the context sets
    // one — `IconHost` does it for every icon built by name.

    ink: Color = { this.textColor },
    weight: number = 1.6,        // stroke width in FINAL pixels, not authored ones

    // 16-box → host size. Multiply the path by this; divide the stroke by it, so
    // the line keeps its true weight instead of scaling with the drawing.

    unit: number = { this.width / 16 }
    ]

/*
# Segmented

A row of mutually exclusive choices — the control you reach for when the options
are few, named, and worth showing all at once. Its choices are **data**, like
`Menu`'s items and `DataGrid`'s columns:

```declare-fragment
Segmented [ width = 300, value = { app.page },
    choices = { [ ({ id: "controls", label: "Controls" }),
                 ({ id: "table",    label: "Table" }),
                 ({ id: "grid",     label: "DataGrid" }) ] },
    input(v: object) { app.page = "" + v }
    ]
```

## Why data, and not `Segment` children

Because the sliding highlight cannot be built any other way. The pill has to know
which choice is selected and how wide each one is, and a constraint may not ask
the view tree that: `childViews` carries **set membership only**, so `.length` is
live while anything reaching into the collection is refused —
`aggregation over a reactive node collection … derive from data [DECLARE7001]`.
The compiler names the answer.

It is also the mainstream shape. UIKit's segments are titles in an array, SwiftUI
picks from a `ForEach`, Ant Design takes `options`; only Material and WinUI name
the item at all, and both compound it. A bare `Segment` class was the minority
pattern — and bare enough that two apps in this corpus had taken the name for a
paragraph of prose.

## Equal widths — a choice, not a limitation

Segments divide the control's width evenly. This is a DESIGN decision and it
could be otherwise: a `Layout`'s `place()` may aggregate over children — that is
how `SimpleLayout` sizes a variable-width row — so a strategy that placed each
segment by its own label and interpolated the pill between neighbours is
buildable. The `DECLARE7001` refusal binds constraints reaching into the view
tree, not the layout strategy whose job that is. Three reasons not to:

- **The systems that call this a segmented control agree.** UIKit divides evenly
  by default (`apportionsSegmentWidthByContent` is opt-in), as does SwiftUI's
  segmented `Picker`. The ones that size to content — Bootstrap, Ant — are really
  styling a row of buttons.
- **Apple's guidance makes it a content rule**: keep segment labels short and
  similar in length. Equal width enforces that rather than tolerating it. One long
  label makes the whole control look wrong, which is the feedback you want.
- **The sliding pill.** At equal widths it translates at constant width. At
  variable widths it would have to morph its width WHILE travelling, which reads
  as rubbery and worsens the more the labels differ. Most platforms never meet
  this, because their highlight pops.

The cost is real and worth stating plainly: **a `Segmented` does not self-size to
its labels.** Set `width`, or accept `segMin × choices.length`.

## The pill

The highlight springs a NORMALIZED LANE — a float index — not pixels. `x` is then
`lane × segW`, so a resize recomputes `segW` and the pill **snaps** to the right
place instead of skating across the bar on every layout change. Calendar's tab
strip discovered this; it is the one thing the bespoke copies did better than the
library, and it is now here.

The look is the library's: the chosen segment wears a raised `surface` pill with
a hairline. The motion is calendar's. Neither app was wrong about the half it got
right (`chrome-divergences.md` D9).
*/



class Segmented extends View [
    // the marker (the wrap-probe discipline)

    isSegmented: boolean = true,

    choices: array = [],           // a BARE literal: it owns a cell, so a use-site value wires
    value: object = null,
    disabled: boolean = false,

    height = 30,
    cornerRadius = 8,
    fill = { this.theme.control },

    segMin: number = 96,            // per-segment width when the author sets none
    count:  number = { Math.max(1, ((this.choices ?? [])).length) },
    width  = { this.count * this.segMin },
    segW:   number = { (this.width - 4) / this.count },

    // Which choice is live, as an INDEX — from the data, which is the only place
    // this question can be asked. −1 (nothing selected) parks the pill at 0 and
    // hides it rather than springing to a phantom slot.

    idx: number = { ((this.choices ?? [])).findIndex((c) => c.id === this.value) },

    // ── the delivery seam ─────────────────────────────────────────────────

    input(v: object) { this.value = v },
    pick(v: object) { this.input(v) },

    // the member walk (handlers only — the for-of discipline)

    segs() -> array {
        const out = []
        for (const c of this.children) { if ((c).isSegment === true) out.push(c) }
        return out
        },

    // arrows ROVE focus across the segments (a focused segment calls this);
    // Space/Enter on the landed segment picks — so an inactive choice is
    // reachable and selectable entirely from the keyboard

    roveFrom(seg: View, d: number) {
        const ss = this.segs()
        const i = ss.indexOf(seg)
        if (i < 0) return
        const n = Math.max(0, Math.min(ss.length - 1, i + d))
        if (n != i) Focus.focus(ss[n])
        },

    // THE PILL. `lane` is a float index the spring drives; `x` multiplies it by
    // the CURRENT segment width, so the pill is correct at any size the moment
    // layout changes and only animates when the selection does.

    lane: number = 0,
    Spring [ attribute = lane, to = { classroot.idx < 0 ? 0 : classroot.idx },
        stiffness = 260, damping = 30, mass = 0.9, epsilon = 0.002 ],

    pill: View [ y = 2, height = { parent.height - 4 }, cornerRadius = 6,
        x = { 2 + (parent).lane * (parent).segW },
        width = { (parent).segW },
        visible = { (parent).idx >= 0 },
        fill = { this.theme.surface },
        stroke = { stroke(1, this.theme.line) } ],

    // The index rides IN the data — replication has no ordinal of its own, and
    // the pill needs one to place each segment.

    items: Dataset [ contents = { ({ rows: ((classroot.choices ?? [])).map((c, i) => ({ ...c, i: i })) }) } ],

    // Replicated as DIRECT children, so a segment's `parent` is the control
    // itself — the pill and the segments are siblings over one cursor.

    datapath = { this.items.value },
    SegmentedItem [ datapath = :rows[] ]
    ]


// One choice. A CONTROL — its own tab stop, Space/Enter activating the pick, so
// the user tabs to an inactive choice and selects it. Materialized from the
// data; not authored directly, which is why it carries no attributes of its own
// beyond what the record gives it.

class SegmentedItem extends Control [
    isSegment: boolean = true,

    height = { parent.height },
    width  = { (parent).segW },
    x      = { 2 + this.$data(["i"]) * (parent).segW },

    on: boolean = { (parent).value === this.$data(["id"]) },

    // Rest, hover and press only — the CHOSEN state is the sliding pill behind
    // these, not a fill of their own. That is what lets it travel between them.

    bg: View [ x = 2, y = 2, width = { parent.width - 4 }, height = { parent.height - 4 },
        cornerRadius = 6,
        fill = { parent.on ? null
               : parent.down ? this.theme.controlPressed
               : parent.hot ? this.theme.controlHover
               : null } ],

    // A choice shows a LABEL or an ICON, whichever the record carries. Every
    // segmented control in this corpus is one or the other — page switches are
    // labelled, appearance switches are the sun/half-disc/moon — so a segment
    // that showed both would be inventing a case nobody has. The record shape is
    // `Menu`'s, so adding it later is additive.

    ink: Color = { this.on || this.hot ? this.theme.text : this.theme.textMuted },

    t: Text [ wrap = false, fontSize = 13, fontWeight = medium,
        visible = { this.$data(["label"]) != null && this.$data(["icon"]) == null },
        x = { (parent.width - this.width) / 2 },
        y = { (parent.height - this.height) / 2 },
        textColor = { parent.ink },
        text = { "" + (this.$data(["label"]) ?? "") } ],

    ico: IconHost [ kind = { "" + (this.$data(["icon"]) ?? "") }, ink = { parent.ink },
        x = { (parent.width - this.width) / 2 },
        y = { (parent.height - this.height) / 2 } ],

    // The control's own disabled flag follows the GROUP's — a segment is not
    // separately disable-able, and a disabled group takes itself out of the tab
    // order rather than offering unreachable stops.

    disabled = { (parent).disabled },

    // A segment MAY be a location. Give a choice a `location` and this segment
    // navigates there itself, in its own `onClick` — which is what makes it
    // visible to link extraction (compiler/src/links.ts reads `app.location = …`
    // out of activation handlers, and `input(v)` is not one; nor could it be,
    // since the destination there depends on `v`, which does not exist at t=0).
    //
    // The docs app is the case that named this: its Guide/Reference switch was
    // the ONLY edge into the reference half of the crawl graph — the class rail
    // is `visible = { mode == "reference" }`, so at the default location its 58
    // links are not in the settled tree at all. When the switch stopped being a
    // link, 58 documents left the static build silently. A second on-page index
    // would be duplicate content; the switch IS the index's front door, so the
    // front door is what had to say where it goes.
    //
    // Empty for every other Segmented in the corpus, and an empty read emits no
    // anchor, so this is inert unless a choice asks for it.

    location: string = { "" + (this.$data(["location"]) ?? "") },

    press()   { if (!this.disabled) (this.parent).pick(this.$data(["id"])) },
    onClick() {
        if (this.disabled) return
        if (classroot.location != "") this.root.location = classroot.location
        this.press()
        },

    onKeyDown(e: KeyEvent) {
        if (this.disabled) return
        if (e.key == "Enter" || e.key == " ") this.press()
        else if (e.key == "ArrowRight" || e.key == "ArrowDown") (this.parent).roveFrom(this, 1)
        else if (e.key == "ArrowLeft" || e.key == "ArrowUp") (this.parent).roveFrom(this, -1)
        },

    // the ring hugs the segment's pill, not its whole box

    focusShape() { return { x: 2, y: 2, w: this.width - 4, h: this.height - 4, rad: 6 } }
    ]

/*
# AppIsland — a whole Declare program running inside a box

`AppIsland` embeds a live Declare application: give it a `program` and it mounts
that program as its own child app — its own reactive graph, input router, and
stage — sized to this view's box. There is no coordinate sync: the tenant fills
the box, so your width/height constraints size it like any view.

It composes `DOMIsland` (the sanctioned foreign-content leaf) and builds the
host's mount key from structured inputs, so callers never hand-splice the
`run:…` wire. The page host (`browser/host-client.js`) sees the key on the box,
resolves the program on its boot ladder — prewarm → cache → in-browser compile,
identical on the dev server and a static host — and renders the child.

- `program` — what to run: a program name, or a relative path
  (`"../../calendar/calendar"` reaches the real app, no copy), or the reserved
  `"__raw__"` live-edit channel (the running program is the host app's
  `liveSource`, recompiled on change). `""` detaches the island — nothing mounts.
- `env` — the embedding environment, in query form (`"dark=1&base=../x/"`),
  delivered to the child's reactive `app.env` at mount and on every change.
  Empty sends none, so the child keeps its own defaults (e.g. system appearance).
- `childName` (inherited from `DOMIsland`) — the reverse channel: the running
  child's `appName` reflected back up, so a host can title itself by what it shows.

The window frame, activation, and titling belong to the caller — a desktop window
adds an `onPointerDown` that raises itself and reads `childName` for its title; the
homepage and the viewer just size the box. This primitive is only the embedding.
*/

class AppIsland extends DOMIsland [
    program: string = "",
    env: string = "",

    // the host mount key: `run:<program>`, with the env query after `|`. No
    // program → empty slot → the island stays detached (DOMIsland unmounts it).

    slot = { this.program == "" ? "" : "run:" + this.program + (this.env == "" ? "" : "|" + this.env) }
    ]

/*
# WrappingLayout — a flow that wraps to new rows

A horizontal flow that WRAPS: children run left to right
`spacing` apart, and when the next one would overflow the view's width it
drops to a new row (`lineSpacing` down; -1, the default, means "same as
spacing"). With room for one row it is a plain row; as the view narrows it
stacks — cards that reflow on a phone with no media query. It owns BOTH
axes of each child (a flow is 2-D); sizes stay the children's own. `align`
justifies each finished row: `start` (left, the default) or `center` (a row
that does not fill the width sits centered).

Division of labor: this is the tool for UNIFORM, replicated collections
that reflow by fitting. Managing NAMED regions per width tier is
ResponsiveLayout's.

Written in Declare over the Layout kernel — the whole strategy is place().
*/

class WrappingLayout extends Layout [
    spacing: number = 0,
    lineSpacing: number = -1,
    align: WrapAlign = start,

    place() {
        const w = this.view == null ? 0 : this.view.width
        const sp = this.spacing
        const ls = this.lineSpacing < 0 ? sp : this.lineSpacing
        const centered = this.align == "center"
        const kids = this.laid()
        const out = []
        let cx = 0
        let cy = 0
        let rowH = 0
        let firstInRow = true
        let rowStart = 0
        // shift a finished row [rowStart, end) right by half its slack
        const justify = (end, rowW) => {
            if (!centered) return
            const off = Math.max(0, (w - rowW) / 2)
            if (off > 0) for (let j = rowStart; j < end; j++) out[j].x = out[j].x + off
        }
        for (let i = 0; i < kids.length; i++) {
            const c = kids[i]
            if (!c.visible) { out.push({ x: cx, y: cy }); continue }   // skipped: reclaim its slot
            const cw = c.width
            const ch = c.height
            // wrap when this child (with its leading gap) would overflow — never
            // on a row's first child, so one over-wide child just overflows
            if (!firstInRow && cx + sp + cw > w) { justify(i, cx); cx = 0; cy = cy + rowH + ls; rowH = 0; firstInRow = true; rowStart = i }
            if (!firstInRow) cx = cx + sp
            out.push({ x: cx, y: cy })
            cx = cx + cw
            rowH = Math.max(rowH, ch)
            firstInRow = false
        }
        justify(kids.length, cx)   // the last (or only) row
        return out
        }
    ]

/*
# Appearance icons — sun, moon, and the half-disc

The Light / System / Dark triad. Five apps built this switch independently and
all five reached for `☀︎ ◐ ☾`, which is the worst case for glyphs: three marks
that must read as ONE family at 14px, drawn by three unrelated parts of whatever
font the platform happens to have. The sun is a heavy sunburst, the moon a thin
crescent, the half-disc a geometric shape — they never matched.

Drawn, they share a circle of the same radius and the same stroke, so they read
as a set: a disc with rays, a disc bitten by a shadow, a disc half filled.
*/



// The three share a disc of one radius. What they do NOT yet share is settled:
// `solid` picks the rendition, and the two are worth comparing on sight rather
// than in prose (test/probe/iconweight.declare puts both against Apple's).
//
// The original argument for filling all three: at 14–18px a 1.6px ring reads far
// lighter than a filled crescent, so filling is what makes them siblings and the
// difference between them is what is SUBTRACTED from the disc — nothing, half, a
// bite. The argument against: Apple's own triad is outline sun, outline crescent,
// HALF-FILLED disc — a mixed language on purpose, because a half-filled disc is
// the one of the three whose meaning IS its fill. Measured, our filled sun runs
// ×2.18 the ink of `sun.max` and our filled moon ×1.21 of `moon`, while our
// half-disc already sits at ×1.03 of `circle.lefthalf.filled` — which says the
// half-disc was never the problem and the other two are carrying the weight.

class SunIcon extends Icon [
    rays: number = 8,
    solid: boolean = false,         // true = the original filled disc; false is Apple's ring
    draw(d: Draw) {
        d.scale(this.unit, this.unit)
        d.fillStyle = this.ink
        d.strokeStyle = this.ink
        d.lineWidth = this.weight / this.unit
        d.lineCap = "round"
        // The ring is drawn a touch smaller than the solid disc: a stroke straddles
        // its path, so an outline at the filled radius reads as the larger mark.
        d.beginPath()
        d.arc(8, 8, classroot.solid ? 3.5 : 3.15, 0, Math.PI * 2, false)
        if (classroot.solid) d.fill()
        else d.stroke()
        for (let i = 0; i < classroot.rays; i++) {
            const a = (i / classroot.rays) * Math.PI * 2
            const c = Math.cos(a), s = Math.sin(a)
            d.beginPath()
            d.moveTo(8 + c * 5.3, 8 + s * 5.3)
            d.lineTo(8 + c * 6.9, 8 + s * 6.9)
            d.stroke()
            }
        }
    ]


// A crescent built as the region between two equal circles — the outer edge from
// one, the bite from a second offset by (3, -3). Both arcs meet exactly at the
// circles' two intersection points, so the horns close to a point instead of
// leaving the tail an arc pair leaves.
//
// One path, two renditions: FILL it and you get a solid crescent; STROKE the same
// closed path and you get Apple's, where the horns taper because the two arcs
// meet at a point. Nothing about the geometry changes — only what is done with it.

class MoonIcon extends Icon [
    solid: boolean = false,         // true = the original filled crescent; false is Apple's
    draw(d: Draw) {
        d.scale(this.unit, this.unit)
        d.beginPath()
        d.arc(8, 8, 5.5, 0.389, 4.323, false)      // outer edge, the long way round
        d.arc(11, 5, 5.5, 3.531, 1.181, true)      // the bite, back to the first horn
        d.closePath()
        if (classroot.solid) { d.fillStyle = this.ink; d.fill() }
        else {
            d.strokeStyle = this.ink
            d.lineWidth = this.weight / this.unit
            d.lineJoin = "round"
            d.stroke()
            }
        }
    ]


// "System" — the same disc, half of it taken away. The ring stays so the empty
// half still reads as part of one object rather than as a gap.

class AutoIcon extends Icon [
    draw(d: Draw) {
        d.scale(this.unit, this.unit)
        d.strokeStyle = this.ink
        d.fillStyle = this.ink
        d.lineWidth = this.weight / this.unit
        d.beginPath()
        d.arc(8, 8, 5.4, Math.PI * 0.5, Math.PI * 1.5, false)
        d.closePath()
        d.fill()
        d.beginPath()
        d.arc(8, 8, 5.4, 0, Math.PI * 2, false)
        d.stroke()
        }
    ]

/*
# FocusRing

The traveling focus indicator — the OpenLaszlo 3.4 `focusoverlay` line, on the
reactive core, at its third form: a SHAPE-HUGGING rounded outline whose
terminus reshapes to the focused control's own silhouette (library-charter §6
— the ring springs position, size, AND cornerRadius; a Radio's row ring, a
pill Switch's ring, and a text field's ring differ because the targets do).

The layered model (charter, ratified):

- **The fact** — the ring listens to Focus (a `Focus [ onFocusChange(v: View) { … } ]` member) and
  tracks the target's root-space geometry on EVERY change, pointer or
  keyboard. A pointer focus PARKS the ring there silently (snap, no show) —
  so the next Tab's flight departs from the control the user just clicked,
  never from a stale perch.
- **Roles, theme-elected** — `theme.focusRing`: `"both"` (or `true`, the
  default) · `"travel"` (flight + the OL idle fade) · `"rest"` (no flight —
  the ring appears in place and stays) · `false` (no ring; the theme's
  components carry the at-rest indication — the invariant lives with the
  THEME+components pair). While keyboard modality holds and the role includes
  rest, the ring RESTS — no idle fade; a pointer press clears modality and
  the ring hides (web :focus-visible semantics).
- **The flight is the flourish** — `theme.focusAnimate = false` (the
  sampler's "Animate focus transitions" toggle) snaps every move; the
  underdamped travel is default-on.

It arrives automatically with any Control-descended component (the OL
`canvas.focusclass` default); declare your own `FocusRing [ ]` (or subclass)
to replace it. Pure chrome: never focusable, never a pointer target.
(v1 limits, recorded: root-space bounds are summed through the parent chain —
a scrolled container is not compensated; the silhouette is the target's
`cornerRadius` — a `focusShape()` override protocol arrives with the
emulation passes.)
*/

class FocusRing extends View [ opacity = 0,

    // an OVERLAY owns the keys (an open menu — Keys.navClaim): the ring
    // stands down while it's up — the menu's rover is the focus story, and
    // a page ring poking around a panel reads as chrome fighting chrome

    overlayUp: boolean = false,
    claims: Keys [ onNavClaim(on: boolean) { classroot.overlayUp = on }
        ],

    // where the ring is HEADED — written by the subscription; the springs chase

    tx: number = 0,
    ty: number = 0,
    tw: number = 0,
    th: number = 0,
    trad: number = 8,
    rad: number = 8,
    shown: boolean = false,
    placed: boolean = false,                     // has the ring EVER had a target to park on?

    // the OL idle fade — TRAVEL role only; a resting ring does not fade

    idle: boolean = false,
    gen:  number = 0,

    // role helpers over the theme election

    ringRole()  { const r = this.theme.focusRing; return r == false ? "off" : r == true || r == null ? "both" : r },
    restRole()  { const r = this.ringRole(); return r == "both" || r == "rest" },
    travelRole() { const r = this.ringRole(); return r == "both" || r == "travel" },

    snapTo() { this.x = this.tx; this.y = this.ty; this.width = this.tw; this.height = this.th; this.rad = this.trad },

    // the target's LIVE silhouette, root-space, from the service's follower —
    // tracked through the parent chain and focusShape(), so an arrow-keyed
    // slider thumb (or a reflowing layout) moves the resting ring with it.
    // The band sits OUTSIDE the silhouette: inner edge touching the control's
    // boundary (the Mac halo's hug), displaced by gap + half the stroke.

    focus: Focus [
        onGeometry(g: FocusGeometry) {
            if (g.root != this.root) return
            // TRAVEL WITH the target's scroller: the ring's surface re-hosts
            // inside the scrolled container and positions in ITS content
            // coordinates — the platform then carries ring and control
            // together, zero lag, no per-scroll re-derive (the sticky-frame
            // inverse). A backend without the ride keeps root-space reactive
            // positioning.
            const prev = (this)._lastTarget
            const prevHome = (this)._lastHome
            const hadHome = (this)._hasHome === true
            const px = classroot.x
            const py = classroot.y
            const homed = classroot.travelWith(g.scroller)
            const gx = homed ? g.homeX : g.x
            const gy = homed ? g.homeY : g.y
            // Crossing scroll HOMES (the bar's button → a control in the
            // scrolled page): the flight must still fly. The ring's current
            // position converts through ROOT space into the DESTINATION
            // home's coordinates — same painted spot, new numbers — and the
            // springs then travel entirely within the new space (correct
            // even if that pane scrolls mid-flight).
            if (hadHome && prevHome != g.scroller) {
                const toRoot = prevHome == null || prevHome == this.root
                    ? ({ x: px, y: py })
                    : (() => { const o = prevHome.rootOrigin(); return ({ x: o.x + px - prevHome.scrollX, y: o.y + py - prevHome.scrollY }) })()
                const dst = !homed || g.scroller == this.root
                    ? toRoot
                    : (() => { const o = g.scroller.rootOrigin(); return ({ x: toRoot.x - o.x + g.scroller.scrollX, y: toRoot.y - o.y + g.scroller.scrollY }) })()
                classroot.x = dst.x
                classroot.y = dst.y
                }
            const gap = typeof classroot.theme.focusRingGap == "number" ? classroot.theme.focusRingGap : 0
            const lw = typeof classroot.theme.focusRingWidth == "number" ? classroot.theme.focusRingWidth : 3
            const iw = typeof classroot.theme.focusRingInnerWidth == "number" ? classroot.theme.focusRingInnerWidth : 0
            const off = gap + iw + lw / 2
            classroot.tx = gx - off; classroot.ty = gy - off
            classroot.tw = g.w + 2 * off; classroot.th = g.h + 2 * off
            classroot.trad = g.rad + off
            // Only a FOCUS CHANGE flies. The same control moving under a resting
            // ring — a dragged slider thumb, a reflow — takes the ring with it
            // rigidly: the springs' targets just moved, so land them NOW. The
            // discriminator is target IDENTITY (a handler-scratch expando — not
            // reactive state, just the previous event's view for comparison).
            ;(this)._lastTarget = g.view
            ;(this)._lastHome = g.scroller
            ;(this)._hasHome = true
            if (prev == g.view) classroot.snapTo()
            },

        onFocusChange(v: View) {
            if (v == null) { classroot.shown = false; return }
            let n = v
            for (; n != null && n.parent != null; n = n.parent) { }
            // Another app on the page (an embedded preview) owns this target — its own
            // ring indicates it; this one stands down rather than chase foreign coordinates.
            if (n != this.root) { classroot.shown = false; return }
            // Pointer focus: PARK silently — geometry current, ring hidden. The next
            // keyboard flight departs from here (the just-clicked control).
            if (!Focus.byKeyboard()) { classroot.shown = false; classroot.snapTo(); classroot.placed = true; return }
            if (classroot.ringRole() == "off") { classroot.shown = false; return }
            // No flight when: the ring has never been placed, the theme suppressed
            // the flourish, or the role is rest-only (appear in place, stay).
            if (!classroot.placed || classroot.theme.focusAnimate == false || !classroot.travelRole()) classroot.snapTo()
            classroot.placed = true
            classroot.shown = true
            classroot.raise()     // chrome stays chrome: above whatever raised last (a Dialog, a Menu)
            // idle fade only for the travel-only role — a resting ring persists
            if (classroot.restRole()) { classroot.idle = false; return }
            classroot.gen = classroot.gen + 1
            const g2 = classroot.gen
            classroot.idle = false
            setTimeout(() => { if (classroot.gen == g2) classroot.idle = true }, 1000)
            }
        ],

    // the travel: underdamped springs = motion toward the target + a little
    // arrival overshoot — the 3.4 bounce, by physics. The radius travels too:
    // the terminus reshapes to the control it surrounds.

    Spring [ attribute = x,      to = { classroot.tx }, stiffness = 220, damping = 16 ],
    Spring [ attribute = y,      to = { classroot.ty }, stiffness = 220, damping = 16 ],
    Spring [ attribute = width,  to = { classroot.tw }, stiffness = 220, damping = 18 ],
    Spring [ attribute = height, to = { classroot.th }, stiffness = 220, damping = 18 ],
    Spring [ attribute = rad,    to = { classroot.trad }, stiffness = 220, damping = 20 ],

    Spring [ attribute = opacity, to = { classroot.shown && !classroot.idle ? 0.9 : 0 }, stiffness = 90, damping = 20 ],

    visible = { this.opacity > 0.02 && !this.overlayUp },

    // pure chrome: never a pointer target — and never on the hover chain
    // either, which is what pointerEvents (unlike a hit-test override) governs

    pointerEvents = "none",

    // the shape-hugging outline — a rounded rect at the sprung radius, drawn,
    // so it re-derives as the radius travels between silhouettes

    // the OL brackets and the shape-hugging outline are ONE rendition at two
    // coverages: four corner-anchored strokes whose straight arms extend
    // toward each edge's midpoint by cov ∈ (0..1]. cov = 1 → arms meet, a
    // closed outline; cov low → open corner brackets ("target sights").
    // Coverage is a pure function of DISTANCE from target, so the physics
    // does the choreography: a flight breaks the ring open mid-air and the
    // settle closes the sights around the new silhouette. Small targets skip
    // the bracket phase (a ring around a radio dot has no arms to open).

    draw(d: Draw) {
        const w = this.width, h = this.height
        const Q = Math.PI / 2
        const dist = Math.abs(this.x - this.tx) + Math.abs(this.y - this.ty) + Math.abs(this.width - this.tw) + Math.abs(this.height - this.th)
        const small = Math.min(w, h) < 40
        // Ruled 2026-07-17: the ring travels as a CLOSED outline, source shape
        // to destination shape — no bracket mode intervening. The sights
        // rendition survives behind `theme.focusSights = true` (data, not a
        // code path) for its possible return: fully open in motion, arms
        // sweeping shut inside the last 16px of settle.
        const cov = this.theme.focusSights == true && !small ? Math.max(0.22, 1 - dist / 16) : 1
        const lw = typeof this.theme.focusRingWidth == "number" ? this.theme.focusRingWidth : 3
        // The indicator is ONE band or TWO, by data: `focusRingInnerWidth` > 0
        // adds an inner stroke between the control and the outer one — the
        // Fluent (Redmond) two-tone focus rectangle, black over white. Both
        // passes are the same outline at different insets; the flight, the
        // sights, and the silhouette machinery are shared, not forked.
        const iw = typeof this.theme.focusRingInnerWidth == "number" ? this.theme.focusRingInnerWidth : 0
        const pass = (ins, lwp, color) => {
            const r = Math.max(1, Math.min(this.rad - ins, Math.min(w, h) / 2 - ins))
            const ax = Math.max(0, ((w - 2 * ins) / 2 - r) * cov)      // horizontal arm length
            const ay = Math.max(0, ((h - 2 * ins) / 2 - r) * cov)      // vertical arm length
            d.strokeStyle = color
            d.lineWidth = lwp
            d.beginPath()
            // each corner: arc + arms, inset symmetrically
            d.moveTo(ins + r + ax, ins); d.lineTo(ins + r, ins); d.arc(ins + r, ins + r, r, -Q, Math.PI, true); d.lineTo(ins, ins + r + ay)
            d.moveTo(w - ins - r - ax, ins); d.lineTo(w - ins - r, ins); d.arc(w - ins - r, ins + r, r, -Q, 0); d.lineTo(w - ins, ins + r + ay)
            d.moveTo(w - ins, h - ins - r - ay); d.lineTo(w - ins, h - ins - r); d.arc(w - ins - r, h - ins - r, r, 0, Q); d.lineTo(w - ins - r - ax, h - ins)
            d.moveTo(ins + r + ax, h - ins); d.lineTo(ins + r, h - ins); d.arc(ins + r, h - ins - r, r, Q, Math.PI); d.lineTo(ins, h - ins - r - ay)
            d.stroke()
            }
        pass(0, lw, typeof this.theme.focusColor == "number" ? this.theme.focusColor : this.theme.accent)
        if (iw > 0) pass((lw + iw) / 2, iw, typeof this.theme.focusRingInnerColor == "number" ? this.theme.focusRingInnerColor : this.theme.surface)
        }
    ]

/*
# Declare docs

The Declare reference, rendered AS a Declare app — self-hosted: Declare
documenting Declare. It loads docs-model.json — the extractor's output
(tools/internal/doc/extract.mjs), one walkable data structure — and renders a
navigable class reference: a left rail of components, a detail pane with each
class's Markdown prose and an attributes table, every doc string rendered by
the runtime Markdown component. This one app is both the in-browser docs and
(once built) the web docs; the live object browser is this same view reached
from an instance.

`{ }` bodies are TypeScript → `0x…` colors and expressions; `[ ]` literal
slots take `#…` / named colors. Every color reads `theme.<token>` — one
prevailing record on the App (see it there), so the whole document reskins
from one place.
*/

use [ SunIcon, AutoIcon, MoonIcon ]

font Sans [ family = "system-ui" ]

font Code [ family = "ui-monospace, SFMono-Regular, monospace" ]   // matches the runtime house code face (PROSE.mono)

/*
## Type tokens

Selection is a PREVAILING slot: these tokens don't opt in themselves — the
detail pane sets `selectable = true` on its container, so all right-pane text
(including Markdown prose) is selectable, while the left rail stays
unselectable chrome.
*/

class Title extends Text [ fontFamily = [Sans, "system-ui", "sans-serif"],
    fontWeight = semibold, textColor = { this.theme.text }
    ]


class Muted extends Text [ fontFamily = [Sans, "system-ui", "sans-serif"],
    textColor = { this.theme.textMuted }
    ]


class Mono extends Text [ fontFamily = [Code, "ui-monospace", "monospace"] ]

// a component tab in the left rail — selection is one App attribute
// (`app.selected`, the class name); a tab lights when it matches and sets it
// on click, so the whole navigator is one string

class ClassTab extends View [ width = { parent.width }, height = 32, cornerRadius = 6,
    cname:   string = "",
    fill = { this.root.selected == classroot.cname ? this.theme.sel : this.hovered ? this.theme.control : null },
    onClick()     { this.root.refAt = classroot.cname; this.root.location = "reference/" + classroot.cname; this.root.showPage() },
    lbl: Mono [ x = 12, y = 8, fontSize = 14, wrap = false,
        text = { classroot.cname },
        textColor = { this.root.selected == classroot.cname ? this.theme.text : this.theme.tabIdle } ]
    ]


/*
## Reference rows

One row per documented member. `AttrRow` is an attribute: the signature line
(name : type = default), the prevailing / read-only badges, then its prose.
`MethodRow` and `EventRow` are the method and event forms — the full
signature with the name emphasized (a method), or the handler signature
(`onClick()`, an event), then the prose.
*/

class AttrRow extends View [ width = { parent.width },
    aname: string = { this.$data(["name"]) },              // the attribute's name — the jump index matches on it
    live:  boolean = false,                 // page-active, threaded down to any inline island
    layout: SimpleLayout [ axis = y, spacing = 6 ],

    // name  : type  = default   — the signature, mono, one line

    sig: View [ width = { parent.width },
        layout: SimpleLayout [ axis = x, spacing = 8 ],
        Mono [ fontSize = { 15 * this.root.fontScale }, fontWeight = semibold, textColor = { this.theme.text }, text = { this.$data(["name"]) } ],
        Mono [ fontSize = { 15 * this.root.fontScale }, textColor = { this.theme.accentSecondary }, text = { ": " + this.$data(["type"]) } ],
        Mono [ fontSize = { 14 * this.root.fontScale }, textColor = { this.theme.sigDim },
            text = { this.$data(["default"]) != null ? "= " + this.$data(["default"]) : "" } ]
        ],

    // prevailing / read-only badges, only when either holds

    flags: Mono [ fontSize = { 12 * this.root.fontScale }, textColor = { this.theme.eyebrow },
        visible = { this.$data(["prevailing"]) || this.$data(["readOnly"]) },
        text = { [this.$data(["prevailing"]) ? "prevailing" : "", this.$data(["readOnly"]) ? "read-only" : ""].filter(Boolean).join("  ·  ") } ],

    // the captured doc — prose + any inline runnable islands; dimmed for the reference

    Block [ datapath = :docSegs[], width = { parent.width },
        live = { classroot.live }, tone = { this.theme.refDim }, lead = 1.6 ]
    ]


// The signature string (`set(path: string, v: unknown): void`) comes whole from
// the model; a `:sig.slice()` would be MIS-READ as a datapath (the `.` extends
// the path), so the datapath values are captured into plain attributes first
// and sliced in JS.

class MethodRow extends View [ width = { parent.width },
    aname:    string = { this.$data(["name"]) },
    sigfull:  string = { this.$data(["signature"]) },
    tailtext: string = { this.sigfull.slice(this.aname.length) },   // "(path: …): void"
    live:     boolean = false,
    layout: SimpleLayout [ axis = y, spacing = 6 ],

    sig: View [ width = { parent.width },
        layout: SimpleLayout [ axis = x, spacing = 0 ],
        Mono [ fontSize = { 15 * this.root.fontScale }, fontWeight = semibold, textColor = { this.theme.text }, text = { classroot.aname } ],
        Mono [ fontSize = { 15 * this.root.fontScale }, textColor = { this.theme.mtail }, text = { classroot.tailtext } ]
        ],

    Block [ datapath = :docSegs[], width = { parent.width },
        live = { classroot.live }, tone = { this.theme.refDim }, lead = 1.6 ]
    ]


class EventRow extends View [ width = { parent.width },
    aname: string = { this.$data(["name"]) },
    live:  boolean = false,
    layout: SimpleLayout [ axis = y, spacing = 6 ],

    sig: Mono [ fontSize = { 15 * this.root.fontScale }, fontWeight = semibold, textColor = { this.theme.text }, text = { this.$data(["signature"]) } ],

    Block [ datapath = :docSegs[], width = { parent.width },
        live = { classroot.live }, tone = { this.theme.refDim }, lead = 1.6 ]
    ]


/*
## The live example

An editable source field beside a running preview — the SAME machinery as the
homepage's editable demos: a `TextInput` seeded from the demo source that
republishes edits on `app.liveSource`, and an `AppIsland` the host mounts
the compiled child app into. Both are keyed by the CLASS NAME: the editor
seeds from `app.demoSources[<Class>]` (the server populates this from
apps/docs/demos/), and the island's `program = <Class>` is what the host
wires.
*/

class DocField extends TextInput [ multiline = true, spellcheck = false, wrap = false,
    fontFamily = [Code, "ui-monospace", "monospace"], fontSize = { 13 * this.root.fontScale }, textColor = { this.theme.code },   // 13 = the house code size (PROSE.codeSize)
    editName: string = "",
    src: string = "",

    // Seed the field from the demo source once the subtree exists. (TextInput's
    // `initial` yielding-seed can't be used here: its attach-time guard fires
    // before this field's datapath-sourced `src` constraint is bound, so the seed
    // is skipped. An `onInit` write lands after the model has resolved `src`, and —
    // being an author write, not a constraint — leaves the field freely editable.)

    onInit() { this.text = this.src },
    onInput() { this.root.liveCard = this.editName; this.root.liveSource = this.text }
    ]


// Rendered by datapath replication over the class's 0-or-1 `example` array, so the
// whole island (editor + preview) is CONSTRUCTED only for classes that ship a demo.

class Example extends View [ width = { parent.width },
    cname:  string = { this.$data(["name"]) },
    elines: number = { this.$data(["lines"]) },
    esrc:   string = { this.$data(["source"]) },
    estage: number = { this.$data(["stageH"]) || 250 },   // extractor-measured stage height — the frame FITS the settled app
    live:   boolean = false,             // the parent gates the preview: it mounts only when this is true

    // this island's edit failed to compile (host publishes the report; see RunIsland)

    broken: boolean = { this.root.liveCard == this.cname && this.root.liveReport != "" },
    layout: SimpleLayout [ axis = y, spacing = 0 ],   // the preview frame abuts the code block below, no gap

    head: View [ width = { parent.width },
        layout: SimpleLayout [ axis = y, spacing = 2 ],
        rule: View [ width = { parent.width }, height = 2, fill = { this.theme.rule } ],
        gap:  View [ height = 8 ],
        Title [ fontSize = { 20 * this.root.fontScale }, text = "Example" ]
        ],

    gap12: View [ height = 12 ],         // the title's breathing room (the layout spacing is now 0)

    // the editable source card — coheres with a static code block (the same
    // `chipBg` tint, 8px radius, 13px code face) but is marked LIVE/EDITABLE by an
    // AMBER left bar + label, where a read-only block carries the teal `codeRule`.

    panel: View [ width = { parent.width }, fill = { this.theme.chipBg },
        height = { Math.min(classroot.elines * 15 * this.root.fontScale + 105, 900) },   // 15px/line measured; field pad + 60/8 chrome
        bar:   View [ x = 0, y = 0, width = 3, height = { parent.height }, fill = { classroot.broken ? this.theme.errBar : 0xE6B450 } ],
        fname: Mono [ x = 18, y = 10, fontSize = { 11 * this.root.fontScale }, fontWeight = semibold, textColor = { this.theme.strong },
            text = { classroot.cname + ".declare" } ],

        // the marker is an INVERTED chip — the amber accent as fill, black letters —
        // so "live/editable" reads at a glance, distinct from a read-only block

        tag:   View [ y = 7, height = 17, cornerRadius = 3, fill = 0xE6B450, x = { parent.width - this.width - 14 },
            lbl: Mono [ x = 7, y = 3, fontSize = 10, letterSpacing = 1, fontWeight = semibold, textColor = 0x1A1A1A,
                text = "LIVE · EDITABLE", wrap = false ],
            width = { this.lbl.width + 14 }
            ],

        // Revert — restore the pristine source and republish (see RunIsland)

        rev: View [ y = 5, height = 20, cornerRadius = 6, stroke = { stroke(1, this.theme.line) },
            x = { parent.tag.x - this.width - 10 },
            width = { this.rlbl.width + 16 },
            fill = { this.hovered ? this.theme.control : null },
            onClick() { classroot.panel.field.text = classroot.esrc
                        this.root.liveCard = classroot.cname
                        this.root.liveSource = classroot.esrc },
            rlbl: Text [ x = 8, y = 3, fontFamily = [Sans, "system-ui", "sans-serif"], fontSize = 11, fontWeight = semibold,
                textColor = { parent.hovered ? this.theme.text : this.theme.textMuted }, text = "Revert" ]
            ],

        // a line of breathing room below the label before the code starts

        hair:  View [ x = 18, y = 51, width = { parent.width - 30 }, height = 1, fill = { this.theme.line } ],
        field: DocField [ x = 18, y = 60, width = { parent.width - 30 }, height = { parent.height - 68 },
            editName = { classroot.cname }, src = { classroot.esrc } ]
        ],

    // the compile report at the island (see RunIsland — same teaching surface)

    err: View [ width = { parent.width }, fill = { this.theme.errBg },
        visible = { classroot.broken },
        height = { this.msg.height + 20 },
        bar: View [ x = 0, y = 0, width = 3, height = { parent.height }, fill = { this.theme.errBar } ],
        msg: Text [ x = 18, y = 10, width = { parent.width - 36 }, wrap = true,
            fontFamily = [Code, "ui-monospace", "monospace"], fontSize = { 12 * this.root.fontScale },
            textColor = { this.theme.errText }, text = { this.root.liveReport } ]
        ],

    // the live preview island — the host mounts the compiled child app here. The slot
    // is live ONLY while the parent says so (`live`), so exactly one preview (the one
    // on the visible page) compiles at a time, even though every page is constructed.

    stage: View [ width = { parent.width }, height = { classroot.estage }, fill = { this.theme.chipBg },
        run:     AppIsland [ width = { parent.width }, height = { parent.height },
            program = { classroot.live ? classroot.cname : "" } ],

        // a blue rule (a darker shade of the chipBg box tint) divides the code above from the
        // running app below; the gold spine (drawn OVER both) continues the code's gold left bar
        // down the preview, same x/width

        divider: View [ x = 0, y = 0, width = { parent.width }, height = 2, fill = { this.theme.rule } ],
        spine:   View [ x = 0, y = 0, width = 3, height = { parent.height }, fill = 0xE6B450 ]
        ]
    ]


/*
## Inline examples, woven through the prose

Every `declare` code fence in any prose that compiles (as-is, or wrapped in
`App […]`) becomes a `RunIsland`: the source above, its live preview below —
edit and it re-runs. The extractor wrote its source to
`apps/docs/demos/<id>.declare`, so the host seeds and mounts it exactly
like the homepage's demos. `live` (threaded from the page) keeps the
preview's slot empty until its page is the one on screen, so only the visible
page's islands ever compile.
*/

class RunIsland extends View [ width = { parent.width },
    rid:    string  = { this.$data(["id"]) },
    rsrc:   string  = { this.$data(["source"]) },
    rlines: number  = { this.$data(["lines"]) },
    rstage: number  = { this.$data(["stageH"]) || 200 },   // extractor-measured stage height — the frame FITS the settled app
    live:   boolean = false,

    // this island's edit is the one that failed to compile — the host publishes the
    // report on app.liveReport (cleared by a clean compile), keyed by app.liveCard

    broken: boolean = { this.root.liveCard == this.rid && this.root.liveReport != "" },
    layout: SimpleLayout [ axis = y, spacing = 0 ],   // the preview frame abuts the code block, no gap

    // same code-box grammar as a static block (chipBg tint, 8px radius, 13px face),
    // marked live/editable by the amber bar + label (a read-only block is teal).

    // height: measured 15px/line at the 13px code face, plus the field's ~20px
    // padding and the 46+8 header/footer chrome — so the code fits without an
    // inner scrollbar up to the cap

    editor: View [ width = { parent.width }, fill = { this.theme.chipBg },
        height = { Math.min(classroot.rlines * 15 * this.root.fontScale + 93, 900) },
        bar:  View [ x = 0, y = 0, width = 3, height = { parent.height }, fill = { classroot.broken ? this.theme.errBar : 0xE6B450 } ],
        tag:  View [ x = 18, y = 7, height = 17, cornerRadius = 3, fill = 0xE6B450,
            lbl: Mono [ x = 7, y = 3, fontSize = 10, letterSpacing = 1, fontWeight = semibold, textColor = 0x1A1A1A,
                text = "LIVE · EDITABLE", wrap = false ],
            width = { this.lbl.width + 14 }
            ],

        // Revert restores the pristine source and republishes it — the way back the
        // guide owes a reader it just told to break something

        rev: View [ y = 5, height = 20, cornerRadius = 6, stroke = { stroke(1, this.theme.line) },
            x = { parent.width - this.width - 10 },
            width = { this.rlbl.width + 16 },
            fill = { this.hovered ? this.theme.control : null },
            onClick() { classroot.editor.field.text = classroot.rsrc
                        this.root.liveCard = classroot.rid
                        this.root.liveSource = classroot.rsrc },
            rlbl: Text [ x = 8, y = 3, fontFamily = [Sans, "system-ui", "sans-serif"], fontSize = 11, fontWeight = semibold,
                textColor = { parent.hovered ? this.theme.text : this.theme.textMuted }, text = "Revert" ]
            ],
        hint: Muted [ y = 9, fontSize = { 11 * this.root.fontScale }, italic = true, text = "runs live below ↓",
            x = { parent.rev.x - this.width - 12 } ],

        // a line of breathing room below the label before the code starts

        field: DocField [ x = 18, y = 46, width = { parent.width - 30 }, height = { parent.height - 54 },
            editName = { classroot.rid }, src = { classroot.rsrc } ]
        ],

    // the compile report, at the island — the diagnostic is a teaching surface, so a
    // broken edit shows its error right here (the last good render stays below it)

    err: View [ width = { parent.width }, fill = { this.theme.errBg },
        visible = { classroot.broken },
        height = { this.msg.height + 20 },
        bar: View [ x = 0, y = 0, width = 3, height = { parent.height }, fill = { this.theme.errBar } ],
        msg: Text [ x = 18, y = 10, width = { parent.width - 36 }, wrap = true,
            fontFamily = [Code, "ui-monospace", "monospace"], fontSize = { 12 * this.root.fontScale },
            textColor = { this.theme.errText }, text = { this.root.liveReport } ]
        ],

    stage: View [ width = { parent.width }, height = { classroot.rstage }, fill = { this.theme.chipBg },
        run:     AppIsland [ width = { parent.width }, height = { parent.height },
            program = { classroot.live ? classroot.rid : "" } ],
        divider: View [ x = 0, y = 0, width = { parent.width }, height = 2, fill = { this.theme.rule } ],
        spine:   View [ x = 0, y = 0, width = 3, height = { parent.height }, fill = 0xE6B450 ]
        ]
    ]


// one prose segment — a run of Markdown text OR (0-or-1) a runnable island. A code
// block that didn't compile stays folded into the Markdown as a static code fence.
// `tone`/`lead` let a caller dim the prose (the reference runs dimmer than the guide).

class Block extends View [ width = { parent.width },
    live: boolean = false,
    tone: Color   = { this.theme.body },
    lead: number  = 1.6,
    layout: SimpleLayout [ axis = y, spacing = 14 ],
    md: Markdown [ width = { parent.width }, lineHeight = { classroot.lead }, bodyColor = { classroot.tone }, scale = { this.root.fontScale }, dark = { this.root.darkUI },
        visible = { this.$data(["md"]) != "" }, text = { this.$data(["md"]) },
        onLink(href: string) { this.root.openDocLink(href) }
        ],
    RunIsland [ datapath = :code[], width = { parent.width }, live = { classroot.live } ]
    ]


/*
## The class page

One class's whole detail page — shown only when it is the selection. All the
detail pages overlay at (0,0); `visible` picks the selected one, so switching
is a single boolean and the scroll pane measures only the live page.
*/

class ClassDetail extends View [ width = { parent.width },
    cname: string = "",
    visible = { this.root.selected == classroot.cname },

    // this page is on screen — the gate every inline preview reads before it mounts

    pageLive: boolean = { this.root.mode == "reference" && this.root.selected == classroot.cname },
    layout: SimpleLayout [ axis = y, spacing = 18 ],

    // Jump: find the member row (attribute, method, or event) carrying this name and
    // scroll it into view. Imperative, so it lives in the click handler (View.reveal,
    // the runtime scroll-into-view primitive); every row carries an `aname` to match.

    revealAttr(name: string) {
        for (const box of [this.attrs, this.meths, this.evts]) {
            for (const row of box.children) {
                if (row.aname === name) { row.scrollIntoView(); return }
            }
        }
        },

    // header: the class name + what it extends

    head: View [ width = { parent.width },
        layout: SimpleLayout [ axis = y, spacing = 6 ],
        Title [ fontSize = { 32 * this.root.fontScale }, text = { classroot.cname } ],
        Mono  [ fontSize = { 14 * this.root.fontScale }, textColor = { this.theme.sigDim },
            text = { this.$data(["extends"]) != null ? "class " + classroot.cname + " extends " + this.$data(["extends"])
                                      : "class " + classroot.cname + "  (base)" } ]
        ],

    // the member jump index — one wrap of chips (attributes teal, methods blue, events
    // amber), click to scroll to a definition below. All three kinds share `revealAttr`.

    index: View [ width = { parent.width },
        visible = { this.$data(["attributes","length"]) > 0 || this.$data(["methods","length"]) > 0 || this.$data(["events","length"]) > 0 },
        layout: WrappingLayout [ spacing = 8, lineSpacing = 8 ],

        // attribute chips

        View [ datapath = :attributes[],
            aname: string = { this.$data(["name"]) },
            height = 26, cornerRadius = 6, fill = { this.hovered ? this.theme.chipHov : this.theme.chipBg },
            onClick() { classroot.revealAttr(this.aname) },
            lbl: Mono [ x = 10, y = 5, fontSize = { 13 * this.root.fontScale }, textColor = { this.theme.chipTeal }, text = { parent.aname } ],
            width = { this.lbl.width + 20 }
            ],

        // method chips — name()

        View [ datapath = :methods[],
            aname: string = { this.$data(["name"]) },
            height = 26, cornerRadius = 6, fill = { this.hovered ? this.theme.mchipHov : this.theme.mchipBg },
            onClick() { classroot.revealAttr(this.aname) },
            lbl: Mono [ x = 10, y = 5, fontSize = { 13 * this.root.fontScale }, textColor = { this.theme.chipBlue }, text = { parent.aname + "()" } ],
            width = { this.lbl.width + 20 }
            ],

        // event chips — the handler signature

        View [ datapath = :events[],
            aname: string = { this.$data(["name"]) },
            height = 26, cornerRadius = 6, fill = { this.hovered ? this.theme.echipHov : this.theme.echipBg },
            onClick() { classroot.revealAttr(this.aname) },
            lbl: Mono [ x = 10, y = 5, fontSize = { 13 * this.root.fontScale }, textColor = { this.theme.chipAmber }, text = { this.$data(["signature"]) } ],
            width = { this.lbl.width + 20 }
            ]
        ],

    // the class prose — dimmed, with any inline runnable examples woven in

    Block [ datapath = :docSegs[], width = { parent.width },
        live = { classroot.pageLive }, tone = { this.theme.refDim }, lead = 1.6 ],

    // attributes (hidden for a class that documents none — e.g. Dataset)

    attrsHead: View [ width = { parent.width }, visible = { this.$data(["attributes","length"]) > 0 },
        layout: SimpleLayout [ axis = y, spacing = 2 ],
        rule: View [ width = { parent.width }, height = 2, fill = { this.theme.rule } ],
        gap:  View [ height = 8 ],
        Title [ fontSize = { 20 * this.root.fontScale }, text = "Attributes" ]
        ],
    attrs: View [ width = { parent.width }, visible = { this.$data(["attributes","length"]) > 0 },
        layout: SimpleLayout [ axis = y, spacing = 22 ],
        AttrRow [ datapath = :attributes[], width = { parent.width }, live = { classroot.pageLive } ]
        ],

    // methods (hidden for a class that documents none)

    methsHead: View [ width = { parent.width }, visible = { this.$data(["methods","length"]) > 0 },
        layout: SimpleLayout [ axis = y, spacing = 2 ],
        rule: View [ width = { parent.width }, height = 2, fill = { this.theme.rule } ],
        gap:  View [ height = 8 ],
        Title [ fontSize = { 20 * this.root.fontScale }, text = "Methods" ]
        ],
    meths: View [ width = { parent.width }, visible = { this.$data(["methods","length"]) > 0 },
        layout: SimpleLayout [ axis = y, spacing = 22 ],
        MethodRow [ datapath = :methods[], width = { parent.width }, live = { classroot.pageLive } ]
        ],

    // events (hidden for a class that documents none)

    evtsHead: View [ width = { parent.width }, visible = { this.$data(["events","length"]) > 0 },
        layout: SimpleLayout [ axis = y, spacing = 2 ],
        rule: View [ width = { parent.width }, height = 2, fill = { this.theme.rule } ],
        gap:  View [ height = 8 ],
        Title [ fontSize = { 20 * this.root.fontScale }, text = "Events" ]
        ],
    evts: View [ width = { parent.width }, visible = { this.$data(["events","length"]) > 0 },
        layout: SimpleLayout [ axis = y, spacing = 22 ],
        EventRow [ datapath = :events[], width = { parent.width }, live = { classroot.pageLive } ]
        ],

    // the live, editable example — replicated 0-or-1 times, so it's built only when
    // the class ships a demo (apps/docs/demos/<Class>.declare). Its preview is
    // live only while this class is the reference selection.

    exampleBox: View [ width = { parent.width }, visible = { this.$data(["example","length"]) > 0 },
        layout: SimpleLayout [ axis = y, spacing = 18 ],
        Example [ datapath = :example[], width = { parent.width },
            live = { this.root.mode == "reference" && this.root.selected == classroot.cname } ]
        ],

    tail: View [ width = { parent.width }, height = 48 ]
    ]


/*
## The guide

The mode switch, the chapter rail, and a chapter page. The doc app is two
views over one model: a narrative GUIDE and the class REFERENCE. `app.mode`
picks which; each keeps its own selection (`app.chapter` / `app.selected`) so
switching back lands where you left.
*/

// The mode switch is a full-width segmented pair — each tab half the rail, label
// centered — so the rail's primary control reads at the rail's own (fixed) type
// size. Nav chrome does NOT ride app.fontScale: the A-stepper is a reading-comfort
// control for the content pane; the rail keeps its designed sizes.


// one chapter link in the guide rail — lights when it is the current chapter

class ChapterTab extends View [ width = { parent.width }, height = 32, cornerRadius = 6,
    cid: string = { this.$data(["id"]) },
    cnum: number = { this.$data(["num"]) },
    ctitle: string = { this.$data(["short"]) },
    fill = { this.root.chapter == classroot.cid ? this.theme.sel : this.hovered ? this.theme.control : null },
    onClick()     { this.root.guideAt = classroot.cid; this.root.location = "guide/" + classroot.cid; this.root.showPage() },

    // numbered, because the chapters cite each other by number ("chapter 3")

    lbl: Text [ x = 12, y = 8, fontFamily = [Sans, "system-ui", "sans-serif"], fontSize = 14, wrap = false,
        text = { classroot.cnum + ". " + classroot.ctitle },
        textColor = { this.root.chapter == classroot.cid ? this.theme.text : this.theme.tabIdle } ]
    ]


// one Part in the guide rail — an eyebrow over that part's chapter links

class PartGroup extends View [ width = { parent.width },
    layout: SimpleLayout [ axis = y, spacing = 3 ],
    p: string = { this.$data(["part"]) },
    g:       View [ height = 14 ],
    eyebrow: Mono [ fontSize = 12, letterSpacing = 1.4, fontWeight = semibold, textColor = { this.theme.textMuted }, text = { classroot.p.toUpperCase() } ],
    g2:      View [ height = 4 ],
    ChapterTab [ datapath = :chapters[] ]
    ]


// one chapter page — the chapter as ordered segments (prose + inline runnable islands),
// then its optional flagship demo. Every ```declare block that compiles is a live island.

class ChapterDetail extends View [ width = { parent.width },
    cid: string = { this.$data(["id"]) },
    visible = { this.root.mode == "guide" && this.root.chapter == classroot.cid },
    pageLive: boolean = { this.root.mode == "guide" && this.root.chapter == classroot.cid },
    layout: SimpleLayout [ axis = y, spacing = 20 ],

    // The chapter's content is its OWN file (chapters/<id>.json — the
    // extractor's per-chapter projection), fetched EAGERLY at construction:
    // the model carries only the spine, first paint waits only for the
    // chapter the location names, and the rest stream in behind it — so
    // switches are instant once landed, and a future in-app search can
    // derive over the whole resident fleet. The crawl pulls these files
    // through its data resolver; a missing one fails the build loudly.

    src: DataSource [ ],
    onInit() { this.src.url = "chapters/" + this.$data(["id"]) + ".json"; this.src.fetch() },

    loading: Text [ visible = { classroot.src.loading }, fontSize = { 14 * this.root.fontScale }, textColor = { this.theme.textMuted }, text = "Loading the chapter…" ],
    failed:  Text [ visible = { classroot.src.failed }, fontSize = { 14 * this.root.fontScale }, textColor = { this.theme.textMuted }, wrap = true, width = { parent.width },
        text = { "The chapter did not load — " + (classroot.src.error || "") } ],

    // the guide is the primary reading surface: brighter body, looser leading (Block defaults)

    content: View [ width = { parent.width }, visible = { classroot.src.loaded }, datapath = { classroot.src.value },
        layout: SimpleLayout [ axis = y, spacing = 20 ],

        Block [ datapath = :segs[], width = { parent.width }, live = { classroot.pageLive } ],

        // a flagship runnable example the chapter opts into with `<!-- demo: <Class> -->`

        demoBox: View [ width = { parent.width }, visible = { this.$data(["demo","length"]) > 0 },
            Example [ datapath = :demo[], width = { parent.width }, live = { classroot.pageLive } ]
            ]
        ],
    tail: View [ width = { parent.width }, height = 60 ]
    ]


/*
## The font-size stepper

Three differently-sized "A"s — small · reset · large. Each cell is a centered
"A" whose glyph size signals the action: the small A shrinks, the middle A
resets to the default, the large A grows. The glyphs are FIXED (not
`* app.fontScale`) so the control itself never zooms. Every doc `fontSize`
reads `{ N * app.fontScale }` (and Markdown takes `scale`), so one attribute
zooms the whole document.
*/

class SizeBtn extends View [ width = 32, height = 30, cornerRadius = 6,
    glyph: number = 14,
    delta: number = 0,          // delta 0 = reset to the default
    fill = { this.hovered ? this.theme.control : null },
    onClick() { this.root.fontScale = classroot.delta == 0 ? 1.0
                    : Math.max(0.7, Math.min(1.6, Math.round((this.root.fontScale + classroot.delta) * 100) / 100)) },
    lbl: Text [ fontFamily = [Sans, "system-ui", "sans-serif"], fontWeight = semibold,
        fontSize = { classroot.glyph }, textColor = { this.theme.textMuted }, text = "A",
        x = { (parent.width - this.width) / 2 }, y = { (parent.height - this.height) / 2 } ]
    ]


// the theme switch — ☀ light · ◐ follow the system · ☾ dark. Selection is one
// App attribute (`themeMode`); the theme record derives from it, so the whole
// app (and every island's chrome) reskins from this row.


/*
## The app

A fixed left rail plus a scrolling detail pane, over the model.
*/

App [ fill = { this.theme.bg }, appName = "Declare Docs",

    /* Navigation is ONE string — `location`, the URL fragment (docs/system-design/location.md).
       The grammar is this app's own: `<mode>/<cursor>[@heading]` (`guide/04-tree`,
       `reference/Slider`, `guide/04-tree@named-views`). The declared initial is the
       default, so a fresh `docs.declare` shows the first guide chapter with a clean
       URL (§3). mode/chapter/selected DERIVE from it and are NEVER assigned — every
       tab and link writes `location`, back/forward writes it back, state follows
       (the single-writer rule; assigning derived state would disconnect history). */

    location = "guide/01-thinking-in-declare",

    /* Cross-mode memory (NOT a language feature — two plain remembered cursors).
       `location` only carries the ACTIVE mode's cursor, so switching guide↔reference
       would forget the other side. The tab handlers keep these in step and the mode
       switch consults them, so returning to a mode lands where you left it. */

    guideAt: string = "01-thinking-in-declare",              // last guide chapter visited …
    refAt:   string = "View",                  // … and last reference class

    // The active view, parsed out of `location` (the anchor stripped first — it
    // selects a viewpoint, not a page). The inactive mode's cursor falls back to its
    // remembered value, so its rail/selection stay put behind the other mode.

    mode:     string = { this.root.location.split("@")[0].split("/")[0] || "guide" },
    chapter:  string = { this.root.mode == "guide" ? (this.root.location.split("@")[0].split("/")[1] || "01-thinking-in-declare") : this.root.guideAt },
    selected: string = { this.root.mode == "reference" ? (this.root.location.split("@")[0].split("/")[1] || "View") : this.root.refAt },

    fontScale: number = 1.0,                   // reader font-size zoom for the CONTENT pane (the A stepper drives it; nav is fixed)
    themeMode: string = "system",              // "light" | "system" | "dark" — the ☀◐☾ switch; system follows app.dark

    // the ONE resolved fact every color decision reads — the theme record AND
    // the Markdown rich-element palette must agree, or an override leaves
    // headings in the OS scheme while the chrome switches (seen in the wild)

    darkUI: boolean = { this.themeMode == "dark" || (this.themeMode == "system" && this.root.dark) },

    // the rail is fixed-width chrome: its type no longer rides the reading zoom,
    // and the chapter slugs are short by design, so 232 sits snug around them

    railW: number = 236,
    liveCard: string = "",                     // the demo an inline editor is republishing (name) …
    liveSource: string = "",                   // … and its current source — the host recompiles this pair live

    // (app.liveReport — BUILT-IN — carries the host's rendered compile report; islands display it)

    /* The whole palette in one prevailing record, switched by the OS color
       scheme (`app.dark`, fed live by the runtime) — every color below reads
       `theme.<token>`, so the docs render dark or light and follow the system
       theme as it flips. The dark set is the original tuned palette; the
       live-preview canvas stays a fixed dark in both themes (the demos are
       dark-authored examples). */

    // The HOUSE preset extended, not replaced: the standard tokens underneath,
    // this app's own values over them, and its many domain names (chipBg, rail,
    // modeOn, errBar …) alongside. A standard control dropped in here finds every
    // token it consults; the docs palette is untouched.

    theme = { ({ ...Themes.sanFrancisco(this.darkUI), ...this.root.docsTokens(this.darkUI) }) },

    docsTokens(dark: boolean) -> object { return dark
        ? ({ bg: 0x0B141B, rail: 0x0D1922, surface: 0x0C1620, chipBg: 0x14232E, control: 0x152633, sel: 0x1C2D39, mchipBg: 0x172436, echipBg: 0x241F12, modeOn: 0x1F3B54, chipHov: 0x1C3243, mchipHov: 0x213649, echipHov: 0x332B18, line: 0x1E313C, rule: 0x345B84, edge: 0x1B2C39, accent: 0x4C8DFF, accentSecondary: 0x37E0C8, chipTeal: 0x9FD9CE, chipBlue: 0xA9C7FF, chipAmber: 0xE7C98A, text: 0xE7EEF2, body: 0xC4CFD8, code: 0xC7D3DC, strong: 0xB7C6D2, mtail: 0x9FB3C2, tabIdle: 0x9BB0BE, refDim: 0x98A7B1, textMuted: 0x8A9BA6, modeOff: 0x7C93A2, sigDim: 0x6E8494, eyebrow: 0x55707F, tag: 0x4F6472, errBg: 0x2A1518, errBar: 0xE0525E, errText: 0xF2A0A6 })
        : ({ bg: 0xF6F8FA, rail: 0xECF0F4, surface: 0xFFFFFF, chipBg: 0xE9EFF4, control: 0xE4EBF1, sel: 0xDBE5EE, mchipBg: 0xE7EDF6, echipBg: 0xF5EFE0, modeOn: 0xD1DFF0, chipHov: 0xD9E4ED, mchipHov: 0xD4DEEF, echipHov: 0xECE3CD, line: 0xDCE3E9, rule: 0xB6C8DA, edge: 0xE0E6EC, accent: 0x2E6FE0, accentSecondary: 0x12A594, chipTeal: 0x15806E, chipBlue: 0x3355C2, chipAmber: 0x8F6F28, text: 0x172530, body: 0x2E3B46, code: 0x2B3843, strong: 0x3A4A56, mtail: 0x4F5F6B, tabIdle: 0x55636F, refDim: 0x51606C, textMuted: 0x6A7883, modeOff: 0x74828D, sigDim: 0x84929D, eyebrow: 0x93A0AA, tag: 0xA2AEB8, errBg: 0xFBE9EA, errBar: 0xC93B47, errText: 0x8E2830 }) },

    /* Code-vs-prose coherence, matching the source-viewer reader: prose (and
       every non-code block) wraps to a reading measure while code fills the
       column — so code renders WIDER than prose — and every code block gets a
       tinted box with a teal left bar. All prevailing, so every
       Markdown/HTMLText below inherits it. */

    richTextLayout = { { default: { maxWidth: 560 * this.root.fontScale }, code: { maxWidth: 0 } } },
    codeBackground = { this.theme.chipBg },
    codeRule = { this.theme.accentSecondary },

    docs: DataSource [ url = "../../docs/declare-model.json" ],
    datapath = { this.docs.value },                 // root every :path below into the model
    onInit() { this.docs.fetch() },            // DataSource is explicit-fetch — kick it once, on construction

    /* The `declare-docs:` resolver — this app's packaging of the one symbolic
       link scheme (tools/doc/links.mjs is the registry; the gate keeps every
       target real). Guide and reference IDs navigate IN-APP; the rest resolve
       by the same mechanical id→path rule the registry generates them with, and
       leave through `navigate`. An ordinary href just navigates. */

    // A page switch starts at the TOP of the new page — the detail pane keeps its
    // scroll offset otherwise. The reveal target is a zero-size anchor at the pane's
    // very top, NOT the column: the column sits 40px into the pane, so aligning ITS
    // top with the viewport would eat that margin. Every switch path routes through
    // here: rail tabs and prose links alike.

    showPage() { this.detail.top.scrollIntoView() },

    // An in-app doc link is a location WRITE (docs/system-design/location.md §5) — it navigates
    // the app exactly like a rail tab, so it deep-links, shares, and back-buttons. It
    // also keeps the remembered cursor in step (like the tabs). External schemes still
    // leave through `navigate`.

    openDocLink(href: string) {
        if (!href.startsWith("declare-docs:")) { this.root.navigate(href); return }
        const id = href.slice("declare-docs:".length)
        if (id.startsWith("guide:")) {                       // guide:tree → the chapter whose id ends with the slug
            const slug = id.slice("guide:".length)
            const hit = (this.root.docs.read(["guide"]) || []).find(c => c.id.replace(/^\d+-/, "") == slug)
            if (hit) { this.root.guideAt = hit.id; this.root.location = "guide/" + hit.id; this.root.showPage() }
            return
        }
        if (id == "reference:index") { this.root.location = "reference/" + this.root.refAt; this.root.showPage(); return }
        if (!id.includes(":")) {                             // a reference symbol: View / View.width
            this.root.refAt = id.split(".")[0]; this.root.location = "reference/" + this.root.refAt; this.root.showPage(); return
        }
        if (id.startsWith("operational:")) { this.root.navigate("docs/operational/" + id.slice("operational:".length) + ".md"); return }
        if (id == "spec:core") { this.root.navigate("docs/declare.md"); return }
        if (id == "essay:why-declare") { this.root.navigate("apps/homepage/homepage.declare") }
        },

    /* ## The left rail
       Brand, the Guide/Reference switch, the font-size stepper, then the nav
       for the live mode. */

    rail: View [ x = 0, y = 0, width = { this.root.railW }, height = { this.root.hostHeight }, scrolls = y, fill = { this.theme.rail },
        edge: View [ x = { this.root.railW - 1 }, y = 0, width = 1, height = { this.root.hostHeight }, fill = { this.theme.edge } ],
        col: View [ x = 16, y = 22, width = { this.root.railW - 32 },
            layout: SimpleLayout [ axis = y, spacing = 4 ],

            // the brand, one line — "Declare" in the gradient, "Docs" solid: the same
            // rendition Declare Calendar uses for its own name

            brand: View [ width = { parent.width }, height = 23,

                // the house brand rendition, x-aligned with Calendar's and Viewer's
                // (their bars start the brand at 20; this rail's column starts at 16)

                row: View [ x = 4, height = 22,
                    layout: SimpleLayout [ axis = x, spacing = 5 ],

                    // "Declare" is the way home — navigate() resolves against the
                    // distro root, so this works on either host at any mount point

                    Text [ fontFamily = [Sans, "system-ui", "sans-serif"], fontSize = 18,
                        fontWeight = semibold, letterSpacing = { -0.02 * this.fontSize }, wrap = false,
                        textFill = { gradient("90deg", this.theme.accent, this.theme.accentSecondary) }, text = "Declare",
                        onClick() { this.root.navigate("apps/homepage/homepage.declare") }
                        ],
                    Text [ fontFamily = [Sans, "system-ui", "sans-serif"], fontSize = 18,
                        fontWeight = semibold, letterSpacing = { -0.02 * this.fontSize }, wrap = false,
                        textColor = { this.theme.text }, text = "Docs" ]
                    ]
                ],
            g0:    View [ height = 12 ],

            // Guide / Reference. This was a segmented control in every respect
            // except being one: two hand-styled `View`s, so no focus, no tab
            // stop, no keyboard, no press state (register D10). The delivery
            // seam already fit — the pair's value is `app.mode`, deriving from
            // `app.location`, so a pick writes the location and the value comes
            // back round, which is the single source of truth the location
            // comment above asks for.

            modes: Segmented [ width = { parent.width }, height = 30,
                value = { this.root.mode },
                input(v: object) {
                    this.root.location = ("" + v) == "guide" ? "guide/" + this.root.guideAt : "reference/" + this.root.refAt
                    this.root.showPage()
                    },

                // each half declares WHERE it goes, so the switch is a link the
                // crawler can follow — without it the reference half of the docs
                // is unreachable from the default location (see SegmentedItem)

                choices = { [ ({ id: "guide",     label: "Guide",     location: "guide/" + this.root.guideAt }),
                              ({ id: "reference", label: "Reference", location: "reference/" + this.root.refAt }) ] }
                ],

            // font-size stepper — small / reset / large "A" glyphs zoom every text size

            g_sz:  View [ height = 8 ],
            ctl: View [ width = { parent.width },
                layout: SimpleLayout [ axis = x, spacing = 8 ],
                size: View [ height = 30, cornerRadius = 8, fill = { this.theme.surface }, stroke = { stroke(1, this.theme.line) },
                    layout: SimpleLayout [ axis = x, spacing = 0 ],
                    SizeBtn [ glyph = 11, delta = -0.1 ],
                    div1: View [ width = 1, height = 18, y = 6, fill = { this.theme.line } ],
                    SizeBtn [ glyph = 15, delta = 0 ],
                    div2: View [ width = 1, height = 18, y = 6, fill = { this.theme.line } ],
                    SizeBtn [ glyph = 19, delta = 0.1 ],
                    width = { this.contentWidth }
                    ],
                mode: Segmented [ height = 30, width = 96, iconSize = 15,
                    value = { this.root.themeMode },
                    input(v: object) { this.root.themeMode = "" + v },
                    choices = { [ ({ id: "light",  icon: "SunIcon" }),
                                  ({ id: "system", icon: "AutoIcon" }),
                                  ({ id: "dark",   icon: "MoonIcon" }) ] }
                    ]
                ],

            // guide nav — parts and their chapters

            guideNav: View [ width = { parent.width }, visible = { this.root.mode == "guide" },
                layout: SimpleLayout [ axis = y, spacing = 2 ],
                PartGroup [ datapath = :guideParts[] ]
                ],

            // reference nav — the component list

            refNav: View [ width = { parent.width }, visible = { this.root.mode == "reference" },
                layout: SimpleLayout [ axis = y, spacing = 4 ],
                g1:    View [ height = 14 ],
                eyebrow: Mono [ fontSize = 12, letterSpacing = 1.4, fontWeight = semibold, textColor = { this.theme.textMuted }, text = "COMPONENTS" ],
                g2:    View [ height = 4 ],
                ClassTab [ datapath = :tree[], cname = :name ]
                ]
            ]
        ],

    /* ## The detail pane
       Its own scroller; guide chapters and class pages overlay, the mode +
       selection pick the one live page (so the scroller measures only it).
       `selectable` (prevailing) opts the whole right pane into ordinary
       browser text selection — prose, signatures, Markdown runs — while the
       rail stays chrome. */

    detail: View [ x = { this.root.railW }, y = 0, width = { this.root.hostWidth - this.root.railW }, height = { this.root.hostHeight }, scrolls = y, selectable = true,
        top: View [ x = 0, y = 0, width = 1, height = 1 ],       // showPage's scroll-to-top anchor
        col: View [ x = 48, y = 40, width = { parent.width - 96 },
            guideCol: View [ width = { parent.width }, visible = { this.root.mode == "guide" },
                ChapterDetail [ datapath = :guide[], cid = :id ]
                ],
            refCol: View [ width = { parent.width }, visible = { this.root.mode == "reference" },
                ClassDetail [ datapath = :tree[], cname = :name ]
                ]
            ]
        ]
    ,
    // the traveling focus indicator — provided with the component library

    FocusRing [ ],
]

source:
/*
# Declare docs

The Declare reference, rendered AS a Declare app — self-hosted: Declare
documenting Declare. It loads docs-model.json — the extractor's output
(tools/internal/doc/extract.mjs), one walkable data structure — and renders a
navigable class reference: a left rail of components, a detail pane with each
class's Markdown prose and an attributes table, every doc string rendered by
the runtime Markdown component. This one app is both the in-browser docs and
(once built) the web docs; the live object browser is this same view reached
from an instance.

`{ }` bodies are TypeScript → `0x…` colors and expressions; `[ ]` literal
slots take `#…` / named colors. Every color reads `theme.<token>` — one
prevailing record on the App (see it there), so the whole document reskins
from one place.
*/

use [ SunIcon, AutoIcon, MoonIcon ]

font Sans [ family = "system-ui" ]

font Code [ family = "ui-monospace, SFMono-Regular, monospace" ]   // matches the runtime house code face (PROSE.mono)

/*
## Type tokens

Selection is a PREVAILING slot: these tokens don't opt in themselves — the
detail pane sets `selectable = true` on its container, so all right-pane text
(including Markdown prose) is selectable, while the left rail stays
unselectable chrome.
*/

class Title extends Text [ fontFamily = [Sans, "system-ui", "sans-serif"],
    fontWeight = semibold, textColor = { theme.text }
    ]


class Muted extends Text [ fontFamily = [Sans, "system-ui", "sans-serif"],
    textColor = { theme.textMuted }
    ]


class Mono extends Text [ fontFamily = [Code, "ui-monospace", "monospace"] ]

// a component tab in the left rail — selection is one App attribute
// (`app.selected`, the class name); a tab lights when it matches and sets it
// on click, so the whole navigator is one string

class ClassTab extends View [ width = { parent.width }, height = 32, cornerRadius = 6,
    cname:   string = "",
    fill = { app.selected == classroot.cname ? theme.sel : hovered ? theme.control : null },
    onClick()     { app.refAt = classroot.cname; app.location = "reference/" + classroot.cname; app.showPage() },
    lbl: Mono [ x = 12, y = 8, fontSize = 14, wrap = false,
        text = { classroot.cname },
        textColor = { app.selected == classroot.cname ? theme.text : theme.tabIdle } ]
    ]


/*
## Reference rows

One row per documented member. `AttrRow` is an attribute: the signature line
(name : type = default), the prevailing / read-only badges, then its prose.
`MethodRow` and `EventRow` are the method and event forms — the full
signature with the name emphasized (a method), or the handler signature
(`onClick()`, an event), then the prose.
*/

class AttrRow extends View [ width = { parent.width },
    aname: string = { :name },              // the attribute's name — the jump index matches on it
    live:  boolean = false,                 // page-active, threaded down to any inline island
    layout: SimpleLayout [ axis = y, spacing = 6 ],

    // name  : type  = default   — the signature, mono, one line

    sig: View [ width = { parent.width },
        layout: SimpleLayout [ axis = x, spacing = 8 ],
        Mono [ fontSize = { 15 * app.fontScale }, fontWeight = semibold, textColor = { theme.text }, text = { :name } ],
        Mono [ fontSize = { 15 * app.fontScale }, textColor = { theme.accentSecondary }, text = { ": " + :type } ],
        Mono [ fontSize = { 14 * app.fontScale }, textColor = { theme.sigDim },
            text = { :default != null ? "= " + :default : "" } ]
        ],

    // prevailing / read-only badges, only when either holds

    flags: Mono [ fontSize = { 12 * app.fontScale }, textColor = { theme.eyebrow },
        visible = { :prevailing || :readOnly },
        text = { [:prevailing ? "prevailing" : "", :readOnly ? "read-only" : ""].filter(Boolean).join("  ·  ") } ],

    // the captured doc — prose + any inline runnable islands; dimmed for the reference

    Block [ datapath = :docSegs[], width = { parent.width },
        live = { classroot.live }, tone = { theme.refDim }, lead = 1.6 ]
    ]


// The signature string (`set(path: string, v: unknown): void`) comes whole from
// the model; a `:sig.slice()` would be MIS-READ as a datapath (the `.` extends
// the path), so the datapath values are captured into plain attributes first
// and sliced in JS.

class MethodRow extends View [ width = { parent.width },
    aname:    string = { :name },
    sigfull:  string = { :signature },
    tailtext: string = { this.sigfull.slice(this.aname.length) },   // "(path: …): void"
    live:     boolean = false,
    layout: SimpleLayout [ axis = y, spacing = 6 ],

    sig: View [ width = { parent.width },
        layout: SimpleLayout [ axis = x, spacing = 0 ],
        Mono [ fontSize = { 15 * app.fontScale }, fontWeight = semibold, textColor = { theme.text }, text = { classroot.aname } ],
        Mono [ fontSize = { 15 * app.fontScale }, textColor = { theme.mtail }, text = { classroot.tailtext } ]
        ],

    Block [ datapath = :docSegs[], width = { parent.width },
        live = { classroot.live }, tone = { theme.refDim }, lead = 1.6 ]
    ]


class EventRow extends View [ width = { parent.width },
    aname: string = { :name },
    live:  boolean = false,
    layout: SimpleLayout [ axis = y, spacing = 6 ],

    sig: Mono [ fontSize = { 15 * app.fontScale }, fontWeight = semibold, textColor = { theme.text }, text = { :signature } ],

    Block [ datapath = :docSegs[], width = { parent.width },
        live = { classroot.live }, tone = { theme.refDim }, lead = 1.6 ]
    ]


/*
## The live example

An editable source field beside a running preview — the SAME machinery as the
homepage's editable demos: a `TextInput` seeded from the demo source that
republishes edits on `app.liveSource`, and an `AppIsland` the host mounts
the compiled child app into. Both are keyed by the CLASS NAME: the editor
seeds from `app.demoSources[<Class>]` (the server populates this from
apps/docs/demos/), and the island's `program = <Class>` is what the host
wires.
*/

class DocField extends TextInput [ multiline = true, spellcheck = false, wrap = false,
    fontFamily = [Code, "ui-monospace", "monospace"], fontSize = { 13 * app.fontScale }, textColor = { theme.code },   // 13 = the house code size (PROSE.codeSize)
    editName: string = "",
    src: string = "",

    // Seed the field from the demo source once the subtree exists. (TextInput's
    // `initial` yielding-seed can't be used here: its attach-time guard fires
    // before this field's datapath-sourced `src` constraint is bound, so the seed
    // is skipped. An `onInit` write lands after the model has resolved `src`, and —
    // being an author write, not a constraint — leaves the field freely editable.)

    onInit() { text = src },
    onInput() { app.liveCard = editName; app.liveSource = text }
    ]


// Rendered by datapath replication over the class's 0-or-1 `example` array, so the
// whole island (editor + preview) is CONSTRUCTED only for classes that ship a demo.

class Example extends View [ width = { parent.width },
    cname:  string = { :name },
    elines: number = { :lines },
    esrc:   string = { :source },
    estage: number = { :stageH || 250 },   // extractor-measured stage height — the frame FITS the settled app
    live:   boolean = false,             // the parent gates the preview: it mounts only when this is true

    // this island's edit failed to compile (host publishes the report; see RunIsland)

    broken: boolean = { app.liveCard == cname && app.liveReport != "" },
    layout: SimpleLayout [ axis = y, spacing = 0 ],   // the preview frame abuts the code block below, no gap

    head: View [ width = { parent.width },
        layout: SimpleLayout [ axis = y, spacing = 2 ],
        rule: View [ width = { parent.width }, height = 2, fill = { theme.rule } ],
        gap:  View [ height = 8 ],
        Title [ fontSize = { 20 * app.fontScale }, text = "Example" ]
        ],

    gap12: View [ height = 12 ],         // the title's breathing room (the layout spacing is now 0)

    // the editable source card — coheres with a static code block (the same
    // `chipBg` tint, 8px radius, 13px code face) but is marked LIVE/EDITABLE by an
    // AMBER left bar + label, where a read-only block carries the teal `codeRule`.

    panel: View [ width = { parent.width }, fill = { theme.chipBg },
        height = { Math.min(classroot.elines * 15 * app.fontScale + 105, 900) },   // 15px/line measured; field pad + 60/8 chrome
        bar:   View [ x = 0, y = 0, width = 3, height = { parent.height }, fill = { classroot.broken ? theme.errBar : 0xE6B450 } ],
        fname: Mono [ x = 18, y = 10, fontSize = { 11 * app.fontScale }, fontWeight = semibold, textColor = { theme.strong },
            text = { classroot.cname + ".declare" } ],

        // the marker is an INVERTED chip — the amber accent as fill, black letters —
        // so "live/editable" reads at a glance, distinct from a read-only block

        tag:   View [ y = 7, height = 17, cornerRadius = 3, fill = 0xE6B450, x = { parent.width - this.width - 14 },
            lbl: Mono [ x = 7, y = 3, fontSize = 10, letterSpacing = 1, fontWeight = semibold, textColor = 0x1A1A1A,
                text = "LIVE · EDITABLE", wrap = false ],
            width = { this.lbl.width + 14 }
            ],

        // Revert — restore the pristine source and republish (see RunIsland)

        rev: View [ y = 5, height = 20, cornerRadius = 6, stroke = { stroke(1, theme.line) },
            x = { parent.tag.x - this.width - 10 },
            width = { this.rlbl.width + 16 },
            fill = { hovered ? theme.control : null },
            onClick() { classroot.panel.field.text = classroot.esrc
                        app.liveCard = classroot.cname
                        app.liveSource = classroot.esrc },
            rlbl: Text [ x = 8, y = 3, fontFamily = [Sans, "system-ui", "sans-serif"], fontSize = 11, fontWeight = semibold,
                textColor = { parent.hovered ? theme.text : theme.textMuted }, text = "Revert" ]
            ],

        // a line of breathing room below the label before the code starts

        hair:  View [ x = 18, y = 51, width = { parent.width - 30 }, height = 1, fill = { theme.line } ],
        field: DocField [ x = 18, y = 60, width = { parent.width - 30 }, height = { parent.height - 68 },
            editName = { classroot.cname }, src = { classroot.esrc } ]
        ],

    // the compile report at the island (see RunIsland — same teaching surface)

    err: View [ width = { parent.width }, fill = { theme.errBg },
        visible = { classroot.broken },
        height = { this.msg.height + 20 },
        bar: View [ x = 0, y = 0, width = 3, height = { parent.height }, fill = { theme.errBar } ],
        msg: Text [ x = 18, y = 10, width = { parent.width - 36 }, wrap = true,
            fontFamily = [Code, "ui-monospace", "monospace"], fontSize = { 12 * app.fontScale },
            textColor = { theme.errText }, text = { app.liveReport } ]
        ],

    // the live preview island — the host mounts the compiled child app here. The slot
    // is live ONLY while the parent says so (`live`), so exactly one preview (the one
    // on the visible page) compiles at a time, even though every page is constructed.

    stage: View [ width = { parent.width }, height = { classroot.estage }, fill = { theme.chipBg },
        run:     AppIsland [ width = { parent.width }, height = { parent.height },
            program = { classroot.live ? classroot.cname : "" } ],

        // a blue rule (a darker shade of the chipBg box tint) divides the code above from the
        // running app below; the gold spine (drawn OVER both) continues the code's gold left bar
        // down the preview, same x/width

        divider: View [ x = 0, y = 0, width = { parent.width }, height = 2, fill = { theme.rule } ],
        spine:   View [ x = 0, y = 0, width = 3, height = { parent.height }, fill = 0xE6B450 ]
        ]
    ]


/*
## Inline examples, woven through the prose

Every `declare` code fence in any prose that compiles (as-is, or wrapped in
`App […]`) becomes a `RunIsland`: the source above, its live preview below —
edit and it re-runs. The extractor wrote its source to
`apps/docs/demos/<id>.declare`, so the host seeds and mounts it exactly
like the homepage's demos. `live` (threaded from the page) keeps the
preview's slot empty until its page is the one on screen, so only the visible
page's islands ever compile.
*/

class RunIsland extends View [ width = { parent.width },
    rid:    string  = { :id },
    rsrc:   string  = { :source },
    rlines: number  = { :lines },
    rstage: number  = { :stageH || 200 },   // extractor-measured stage height — the frame FITS the settled app
    live:   boolean = false,

    // this island's edit is the one that failed to compile — the host publishes the
    // report on app.liveReport (cleared by a clean compile), keyed by app.liveCard

    broken: boolean = { app.liveCard == rid && app.liveReport != "" },
    layout: SimpleLayout [ axis = y, spacing = 0 ],   // the preview frame abuts the code block, no gap

    // same code-box grammar as a static block (chipBg tint, 8px radius, 13px face),
    // marked live/editable by the amber bar + label (a read-only block is teal).

    // height: measured 15px/line at the 13px code face, plus the field's ~20px
    // padding and the 46+8 header/footer chrome — so the code fits without an
    // inner scrollbar up to the cap

    editor: View [ width = { parent.width }, fill = { theme.chipBg },
        height = { Math.min(classroot.rlines * 15 * app.fontScale + 93, 900) },
        bar:  View [ x = 0, y = 0, width = 3, height = { parent.height }, fill = { classroot.broken ? theme.errBar : 0xE6B450 } ],
        tag:  View [ x = 18, y = 7, height = 17, cornerRadius = 3, fill = 0xE6B450,
            lbl: Mono [ x = 7, y = 3, fontSize = 10, letterSpacing = 1, fontWeight = semibold, textColor = 0x1A1A1A,
                text = "LIVE · EDITABLE", wrap = false ],
            width = { this.lbl.width + 14 }
            ],

        // Revert restores the pristine source and republishes it — the way back the
        // guide owes a reader it just told to break something

        rev: View [ y = 5, height = 20, cornerRadius = 6, stroke = { stroke(1, theme.line) },
            x = { parent.width - this.width - 10 },
            width = { this.rlbl.width + 16 },
            fill = { hovered ? theme.control : null },
            onClick() { classroot.editor.field.text = classroot.rsrc
                        app.liveCard = classroot.rid
                        app.liveSource = classroot.rsrc },
            rlbl: Text [ x = 8, y = 3, fontFamily = [Sans, "system-ui", "sans-serif"], fontSize = 11, fontWeight = semibold,
                textColor = { parent.hovered ? theme.text : theme.textMuted }, text = "Revert" ]
            ],
        hint: Muted [ y = 9, fontSize = { 11 * app.fontScale }, italic = true, text = "runs live below ↓",
            x = { parent.rev.x - this.width - 12 } ],

        // a line of breathing room below the label before the code starts

        field: DocField [ x = 18, y = 46, width = { parent.width - 30 }, height = { parent.height - 54 },
            editName = { classroot.rid }, src = { classroot.rsrc } ]
        ],

    // the compile report, at the island — the diagnostic is a teaching surface, so a
    // broken edit shows its error right here (the last good render stays below it)

    err: View [ width = { parent.width }, fill = { theme.errBg },
        visible = { classroot.broken },
        height = { this.msg.height + 20 },
        bar: View [ x = 0, y = 0, width = 3, height = { parent.height }, fill = { theme.errBar } ],
        msg: Text [ x = 18, y = 10, width = { parent.width - 36 }, wrap = true,
            fontFamily = [Code, "ui-monospace", "monospace"], fontSize = { 12 * app.fontScale },
            textColor = { theme.errText }, text = { app.liveReport } ]
        ],

    stage: View [ width = { parent.width }, height = { classroot.rstage }, fill = { theme.chipBg },
        run:     AppIsland [ width = { parent.width }, height = { parent.height },
            program = { classroot.live ? classroot.rid : "" } ],
        divider: View [ x = 0, y = 0, width = { parent.width }, height = 2, fill = { theme.rule } ],
        spine:   View [ x = 0, y = 0, width = 3, height = { parent.height }, fill = 0xE6B450 ]
        ]
    ]


// one prose segment — a run of Markdown text OR (0-or-1) a runnable island. A code
// block that didn't compile stays folded into the Markdown as a static code fence.
// `tone`/`lead` let a caller dim the prose (the reference runs dimmer than the guide).

class Block extends View [ width = { parent.width },
    live: boolean = false,
    tone: Color   = { theme.body },
    lead: number  = 1.6,
    layout: SimpleLayout [ axis = y, spacing = 14 ],
    md: Markdown [ width = { parent.width }, lineHeight = { classroot.lead }, bodyColor = { classroot.tone }, scale = { app.fontScale }, dark = { app.darkUI },
        visible = { :md != "" }, text = { :md },
        onLink(href: string) { app.openDocLink(href) }
        ],
    RunIsland [ datapath = :code[], width = { parent.width }, live = { classroot.live } ]
    ]


/*
## The class page

One class's whole detail page — shown only when it is the selection. All the
detail pages overlay at (0,0); `visible` picks the selected one, so switching
is a single boolean and the scroll pane measures only the live page.
*/

class ClassDetail extends View [ width = { parent.width },
    cname: string = "",
    visible = { app.selected == classroot.cname },

    // this page is on screen — the gate every inline preview reads before it mounts

    pageLive: boolean = { app.mode == "reference" && app.selected == classroot.cname },
    layout: SimpleLayout [ axis = y, spacing = 18 ],

    // Jump: find the member row (attribute, method, or event) carrying this name and
    // scroll it into view. Imperative, so it lives in the click handler (View.reveal,
    // the runtime scroll-into-view primitive); every row carries an `aname` to match.

    revealAttr(name: string) {
        for (const box of [this.attrs, this.meths, this.evts]) {
            for (const row of box.children) {
                if (row.aname === name) { row.scrollIntoView(); return }
            }
        }
        },

    // header: the class name + what it extends

    head: View [ width = { parent.width },
        layout: SimpleLayout [ axis = y, spacing = 6 ],
        Title [ fontSize = { 32 * app.fontScale }, text = { classroot.cname } ],
        Mono  [ fontSize = { 14 * app.fontScale }, textColor = { theme.sigDim },
            text = { :extends != null ? "class " + classroot.cname + " extends " + :extends
                                      : "class " + classroot.cname + "  (base)" } ]
        ],

    // the member jump index — one wrap of chips (attributes teal, methods blue, events
    // amber), click to scroll to a definition below. All three kinds share `revealAttr`.

    index: View [ width = { parent.width },
        visible = { :attributes.length > 0 || :methods.length > 0 || :events.length > 0 },
        layout: WrappingLayout [ spacing = 8, lineSpacing = 8 ],

        // attribute chips

        View [ datapath = :attributes[],
            aname: string = { :name },
            height = 26, cornerRadius = 6, fill = { hovered ? theme.chipHov : theme.chipBg },
            onClick() { classroot.revealAttr(this.aname) },
            lbl: Mono [ x = 10, y = 5, fontSize = { 13 * app.fontScale }, textColor = { theme.chipTeal }, text = { parent.aname } ],
            width = { this.lbl.width + 20 }
            ],

        // method chips — name()

        View [ datapath = :methods[],
            aname: string = { :name },
            height = 26, cornerRadius = 6, fill = { hovered ? theme.mchipHov : theme.mchipBg },
            onClick() { classroot.revealAttr(this.aname) },
            lbl: Mono [ x = 10, y = 5, fontSize = { 13 * app.fontScale }, textColor = { theme.chipBlue }, text = { parent.aname + "()" } ],
            width = { this.lbl.width + 20 }
            ],

        // event chips — the handler signature

        View [ datapath = :events[],
            aname: string = { :name },
            height = 26, cornerRadius = 6, fill = { hovered ? theme.echipHov : theme.echipBg },
            onClick() { classroot.revealAttr(this.aname) },
            lbl: Mono [ x = 10, y = 5, fontSize = { 13 * app.fontScale }, textColor = { theme.chipAmber }, text = { :signature } ],
            width = { this.lbl.width + 20 }
            ]
        ],

    // the class prose — dimmed, with any inline runnable examples woven in

    Block [ datapath = :docSegs[], width = { parent.width },
        live = { classroot.pageLive }, tone = { theme.refDim }, lead = 1.6 ],

    // attributes (hidden for a class that documents none — e.g. Dataset)

    attrsHead: View [ width = { parent.width }, visible = { :attributes.length > 0 },
        layout: SimpleLayout [ axis = y, spacing = 2 ],
        rule: View [ width = { parent.width }, height = 2, fill = { theme.rule } ],
        gap:  View [ height = 8 ],
        Title [ fontSize = { 20 * app.fontScale }, text = "Attributes" ]
        ],
    attrs: View [ width = { parent.width }, visible = { :attributes.length > 0 },
        layout: SimpleLayout [ axis = y, spacing = 22 ],
        AttrRow [ datapath = :attributes[], width = { parent.width }, live = { classroot.pageLive } ]
        ],

    // methods (hidden for a class that documents none)

    methsHead: View [ width = { parent.width }, visible = { :methods.length > 0 },
        layout: SimpleLayout [ axis = y, spacing = 2 ],
        rule: View [ width = { parent.width }, height = 2, fill = { theme.rule } ],
        gap:  View [ height = 8 ],
        Title [ fontSize = { 20 * app.fontScale }, text = "Methods" ]
        ],
    meths: View [ width = { parent.width }, visible = { :methods.length > 0 },
        layout: SimpleLayout [ axis = y, spacing = 22 ],
        MethodRow [ datapath = :methods[], width = { parent.width }, live = { classroot.pageLive } ]
        ],

    // events (hidden for a class that documents none)

    evtsHead: View [ width = { parent.width }, visible = { :events.length > 0 },
        layout: SimpleLayout [ axis = y, spacing = 2 ],
        rule: View [ width = { parent.width }, height = 2, fill = { theme.rule } ],
        gap:  View [ height = 8 ],
        Title [ fontSize = { 20 * app.fontScale }, text = "Events" ]
        ],
    evts: View [ width = { parent.width }, visible = { :events.length > 0 },
        layout: SimpleLayout [ axis = y, spacing = 22 ],
        EventRow [ datapath = :events[], width = { parent.width }, live = { classroot.pageLive } ]
        ],

    // the live, editable example — replicated 0-or-1 times, so it's built only when
    // the class ships a demo (apps/docs/demos/<Class>.declare). Its preview is
    // live only while this class is the reference selection.

    exampleBox: View [ width = { parent.width }, visible = { :example.length > 0 },
        layout: SimpleLayout [ axis = y, spacing = 18 ],
        Example [ datapath = :example[], width = { parent.width },
            live = { app.mode == "reference" && app.selected == classroot.cname } ]
        ],

    tail: View [ width = { parent.width }, height = 48 ]
    ]


/*
## The guide

The mode switch, the chapter rail, and a chapter page. The doc app is two
views over one model: a narrative GUIDE and the class REFERENCE. `app.mode`
picks which; each keeps its own selection (`app.chapter` / `app.selected`) so
switching back lands where you left.
*/

// The mode switch is a full-width segmented pair — each tab half the rail, label
// centered — so the rail's primary control reads at the rail's own (fixed) type
// size. Nav chrome does NOT ride app.fontScale: the A-stepper is a reading-comfort
// control for the content pane; the rail keeps its designed sizes.


// one chapter link in the guide rail — lights when it is the current chapter

class ChapterTab extends View [ width = { parent.width }, height = 32, cornerRadius = 6,
    cid: string = { :id },
    cnum: number = { :num },
    ctitle: string = { :short },
    fill = { app.chapter == classroot.cid ? theme.sel : hovered ? theme.control : null },
    onClick()     { app.guideAt = classroot.cid; app.location = "guide/" + classroot.cid; app.showPage() },

    // numbered, because the chapters cite each other by number ("chapter 3")

    lbl: Text [ x = 12, y = 8, fontFamily = [Sans, "system-ui", "sans-serif"], fontSize = 14, wrap = false,
        text = { classroot.cnum + ". " + classroot.ctitle },
        textColor = { app.chapter == classroot.cid ? theme.text : theme.tabIdle } ]
    ]


// one Part in the guide rail — an eyebrow over that part's chapter links

class PartGroup extends View [ width = { parent.width },
    layout: SimpleLayout [ axis = y, spacing = 3 ],
    p: string = { :part },
    g:       View [ height = 14 ],
    eyebrow: Mono [ fontSize = 12, letterSpacing = 1.4, fontWeight = semibold, textColor = { theme.textMuted }, text = { classroot.p.toUpperCase() } ],
    g2:      View [ height = 4 ],
    ChapterTab [ datapath = :chapters[] ]
    ]


// one chapter page — the chapter as ordered segments (prose + inline runnable islands),
// then its optional flagship demo. Every ```declare block that compiles is a live island.

class ChapterDetail extends View [ width = { parent.width },
    cid: string = { :id },
    visible = { app.mode == "guide" && app.chapter == classroot.cid },
    pageLive: boolean = { app.mode == "guide" && app.chapter == classroot.cid },
    layout: SimpleLayout [ axis = y, spacing = 20 ],

    // The chapter's content is its OWN file (chapters/<id>.json — the
    // extractor's per-chapter projection), fetched EAGERLY at construction:
    // the model carries only the spine, first paint waits only for the
    // chapter the location names, and the rest stream in behind it — so
    // switches are instant once landed, and a future in-app search can
    // derive over the whole resident fleet. The crawl pulls these files
    // through its data resolver; a missing one fails the build loudly.

    src: DataSource [ ],
    onInit() { this.src.url = "chapters/" + :id + ".json"; this.src.fetch() },

    loading: Text [ visible = { classroot.src.loading }, fontSize = { 14 * app.fontScale }, textColor = { theme.textMuted }, text = "Loading the chapter…" ],
    failed:  Text [ visible = { classroot.src.failed }, fontSize = { 14 * app.fontScale }, textColor = { theme.textMuted }, wrap = true, width = { parent.width },
        text = { "The chapter did not load — " + (classroot.src.error || "") } ],

    // the guide is the primary reading surface: brighter body, looser leading (Block defaults)

    content: View [ width = { parent.width }, visible = { classroot.src.loaded }, datapath = { classroot.src.value },
        layout: SimpleLayout [ axis = y, spacing = 20 ],

        Block [ datapath = :segs[], width = { parent.width }, live = { classroot.pageLive } ],

        // a flagship runnable example the chapter opts into with `<!-- demo: <Class> -->`

        demoBox: View [ width = { parent.width }, visible = { :demo.length > 0 },
            Example [ datapath = :demo[], width = { parent.width }, live = { classroot.pageLive } ]
            ]
        ],
    tail: View [ width = { parent.width }, height = 60 ]
    ]


/*
## The font-size stepper

Three differently-sized "A"s — small · reset · large. Each cell is a centered
"A" whose glyph size signals the action: the small A shrinks, the middle A
resets to the default, the large A grows. The glyphs are FIXED (not
`* app.fontScale`) so the control itself never zooms. Every doc `fontSize`
reads `{ N * app.fontScale }` (and Markdown takes `scale`), so one attribute
zooms the whole document.
*/

class SizeBtn extends View [ width = 32, height = 30, cornerRadius = 6,
    glyph: number = 14,
    delta: number = 0,          // delta 0 = reset to the default
    fill = { hovered ? theme.control : null },
    onClick() { app.fontScale = classroot.delta == 0 ? 1.0
                    : Math.max(0.7, Math.min(1.6, Math.round((app.fontScale + classroot.delta) * 100) / 100)) },
    lbl: Text [ fontFamily = [Sans, "system-ui", "sans-serif"], fontWeight = semibold,
        fontSize = { classroot.glyph }, textColor = { theme.textMuted }, text = "A",
        x = { (parent.width - this.width) / 2 }, y = { (parent.height - this.height) / 2 } ]
    ]


// the theme switch — ☀ light · ◐ follow the system · ☾ dark. Selection is one
// App attribute (`themeMode`); the theme record derives from it, so the whole
// app (and every island's chrome) reskins from this row.


/*
## The app

A fixed left rail plus a scrolling detail pane, over the model.
*/

App [ fill = { theme.bg }, appName = "Declare Docs",

    /* Navigation is ONE string — `location`, the URL fragment (docs/system-design/location.md).
       The grammar is this app's own: `<mode>/<cursor>[@heading]` (`guide/04-tree`,
       `reference/Slider`, `guide/04-tree@named-views`). The declared initial is the
       default, so a fresh `docs.declare` shows the first guide chapter with a clean
       URL (§3). mode/chapter/selected DERIVE from it and are NEVER assigned — every
       tab and link writes `location`, back/forward writes it back, state follows
       (the single-writer rule; assigning derived state would disconnect history). */

    location = "guide/01-thinking-in-declare",

    /* Cross-mode memory (NOT a language feature — two plain remembered cursors).
       `location` only carries the ACTIVE mode's cursor, so switching guide↔reference
       would forget the other side. The tab handlers keep these in step and the mode
       switch consults them, so returning to a mode lands where you left it. */

    guideAt: string = "01-thinking-in-declare",              // last guide chapter visited …
    refAt:   string = "View",                  // … and last reference class

    // The active view, parsed out of `location` (the anchor stripped first — it
    // selects a viewpoint, not a page). The inactive mode's cursor falls back to its
    // remembered value, so its rail/selection stay put behind the other mode.

    mode:     string = { app.location.split("@")[0].split("/")[0] || "guide" },
    chapter:  string = { app.mode == "guide" ? (app.location.split("@")[0].split("/")[1] || "01-thinking-in-declare") : app.guideAt },
    selected: string = { app.mode == "reference" ? (app.location.split("@")[0].split("/")[1] || "View") : app.refAt },

    fontScale: number = 1.0,                   // reader font-size zoom for the CONTENT pane (the A stepper drives it; nav is fixed)
    themeMode: string = "system",              // "light" | "system" | "dark" — the ☀◐☾ switch; system follows app.dark

    // the ONE resolved fact every color decision reads — the theme record AND
    // the Markdown rich-element palette must agree, or an override leaves
    // headings in the OS scheme while the chrome switches (seen in the wild)

    darkUI: boolean = { themeMode == "dark" || (themeMode == "system" && app.dark) },

    // the rail is fixed-width chrome: its type no longer rides the reading zoom,
    // and the chapter slugs are short by design, so 232 sits snug around them

    railW: number = 236,
    liveCard: string = "",                     // the demo an inline editor is republishing (name) …
    liveSource: string = "",                   // … and its current source — the host recompiles this pair live

    // (app.liveReport — BUILT-IN — carries the host's rendered compile report; islands display it)

    /* The whole palette in one prevailing record, switched by the OS color
       scheme (`app.dark`, fed live by the runtime) — every color below reads
       `theme.<token>`, so the docs render dark or light and follow the system
       theme as it flips. The dark set is the original tuned palette; the
       live-preview canvas stays a fixed dark in both themes (the demos are
       dark-authored examples). */

    // The HOUSE preset extended, not replaced: the standard tokens underneath,
    // this app's own values over them, and its many domain names (chipBg, rail,
    // modeOn, errBar …) alongside. A standard control dropped in here finds every
    // token it consults; the docs palette is untouched.

    theme = { ({ ...Themes.sanFrancisco(darkUI), ...app.docsTokens(darkUI) }) },

    docsTokens(dark: boolean) -> object { return dark
        ? ({ bg: 0x0B141B, rail: 0x0D1922, surface: 0x0C1620, chipBg: 0x14232E, control: 0x152633, sel: 0x1C2D39, mchipBg: 0x172436, echipBg: 0x241F12, modeOn: 0x1F3B54, chipHov: 0x1C3243, mchipHov: 0x213649, echipHov: 0x332B18, line: 0x1E313C, rule: 0x345B84, edge: 0x1B2C39, accent: 0x4C8DFF, accentSecondary: 0x37E0C8, chipTeal: 0x9FD9CE, chipBlue: 0xA9C7FF, chipAmber: 0xE7C98A, text: 0xE7EEF2, body: 0xC4CFD8, code: 0xC7D3DC, strong: 0xB7C6D2, mtail: 0x9FB3C2, tabIdle: 0x9BB0BE, refDim: 0x98A7B1, textMuted: 0x8A9BA6, modeOff: 0x7C93A2, sigDim: 0x6E8494, eyebrow: 0x55707F, tag: 0x4F6472, errBg: 0x2A1518, errBar: 0xE0525E, errText: 0xF2A0A6 })
        : ({ bg: 0xF6F8FA, rail: 0xECF0F4, surface: 0xFFFFFF, chipBg: 0xE9EFF4, control: 0xE4EBF1, sel: 0xDBE5EE, mchipBg: 0xE7EDF6, echipBg: 0xF5EFE0, modeOn: 0xD1DFF0, chipHov: 0xD9E4ED, mchipHov: 0xD4DEEF, echipHov: 0xECE3CD, line: 0xDCE3E9, rule: 0xB6C8DA, edge: 0xE0E6EC, accent: 0x2E6FE0, accentSecondary: 0x12A594, chipTeal: 0x15806E, chipBlue: 0x3355C2, chipAmber: 0x8F6F28, text: 0x172530, body: 0x2E3B46, code: 0x2B3843, strong: 0x3A4A56, mtail: 0x4F5F6B, tabIdle: 0x55636F, refDim: 0x51606C, textMuted: 0x6A7883, modeOff: 0x74828D, sigDim: 0x84929D, eyebrow: 0x93A0AA, tag: 0xA2AEB8, errBg: 0xFBE9EA, errBar: 0xC93B47, errText: 0x8E2830 }) },

    /* Code-vs-prose coherence, matching the source-viewer reader: prose (and
       every non-code block) wraps to a reading measure while code fills the
       column — so code renders WIDER than prose — and every code block gets a
       tinted box with a teal left bar. All prevailing, so every
       Markdown/HTMLText below inherits it. */

    richTextLayout = { { default: { maxWidth: 560 * app.fontScale }, code: { maxWidth: 0 } } },
    codeBackground = { theme.chipBg },
    codeRule = { theme.accentSecondary },

    docs: DataSource [ url = "../../docs/declare-model.json" ],
    datapath = { docs.value },                 // root every :path below into the model
    onInit() { this.docs.fetch() },            // DataSource is explicit-fetch — kick it once, on construction

    /* The `declare-docs:` resolver — this app's packaging of the one symbolic
       link scheme (tools/doc/links.mjs is the registry; the gate keeps every
       target real). Guide and reference IDs navigate IN-APP; the rest resolve
       by the same mechanical id→path rule the registry generates them with, and
       leave through `navigate`. An ordinary href just navigates. */

    // A page switch starts at the TOP of the new page — the detail pane keeps its
    // scroll offset otherwise. The reveal target is a zero-size anchor at the pane's
    // very top, NOT the column: the column sits 40px into the pane, so aligning ITS
    // top with the viewport would eat that margin. Every switch path routes through
    // here: rail tabs and prose links alike.

    showPage() { this.detail.top.scrollIntoView() },

    // An in-app doc link is a location WRITE (docs/system-design/location.md §5) — it navigates
    // the app exactly like a rail tab, so it deep-links, shares, and back-buttons. It
    // also keeps the remembered cursor in step (like the tabs). External schemes still
    // leave through `navigate`.

    openDocLink(href: string) {
        if (!href.startsWith("declare-docs:")) { app.navigate(href); return }
        const id = href.slice("declare-docs:".length)
        if (id.startsWith("guide:")) {                       // guide:tree → the chapter whose id ends with the slug
            const slug = id.slice("guide:".length)
            const hit = (app.docs.read(["guide"]) || []).find(c => c.id.replace(/^\d+-/, "") == slug)
            if (hit) { app.guideAt = hit.id; app.location = "guide/" + hit.id; app.showPage() }
            return
        }
        if (id == "reference:index") { app.location = "reference/" + app.refAt; app.showPage(); return }
        if (!id.includes(":")) {                             // a reference symbol: View / View.width
            app.refAt = id.split(".")[0]; app.location = "reference/" + app.refAt; app.showPage(); return
        }
        if (id.startsWith("operational:")) { app.navigate("docs/operational/" + id.slice("operational:".length) + ".md"); return }
        if (id == "spec:core") { app.navigate("docs/declare.md"); return }
        if (id == "essay:why-declare") { app.navigate("apps/homepage/homepage.declare") }
        },

    /* ## The left rail
       Brand, the Guide/Reference switch, the font-size stepper, then the nav
       for the live mode. */

    rail: View [ x = 0, y = 0, width = { app.railW }, height = { app.hostHeight }, scrolls = y, fill = { theme.rail },
        edge: View [ x = { app.railW - 1 }, y = 0, width = 1, height = { app.hostHeight }, fill = { theme.edge } ],
        col: View [ x = 16, y = 22, width = { app.railW - 32 },
            layout: SimpleLayout [ axis = y, spacing = 4 ],

            // the brand, one line — "Declare" in the gradient, "Docs" solid: the same
            // rendition Declare Calendar uses for its own name

            brand: View [ width = { parent.width }, height = 23,

                // the house brand rendition, x-aligned with Calendar's and Viewer's
                // (their bars start the brand at 20; this rail's column starts at 16)

                row: View [ x = 4, height = 22,
                    layout: SimpleLayout [ axis = x, spacing = 5 ],

                    // "Declare" is the way home — navigate() resolves against the
                    // distro root, so this works on either host at any mount point

                    Text [ fontFamily = [Sans, "system-ui", "sans-serif"], fontSize = 18,
                        fontWeight = semibold, letterSpacing = { -0.02 * fontSize }, wrap = false,
                        textFill = { gradient("90deg", theme.accent, theme.accentSecondary) }, text = "Declare",
                        onClick() { app.navigate("apps/homepage/homepage.declare") }
                        ],
                    Text [ fontFamily = [Sans, "system-ui", "sans-serif"], fontSize = 18,
                        fontWeight = semibold, letterSpacing = { -0.02 * fontSize }, wrap = false,
                        textColor = { theme.text }, text = "Docs" ]
                    ]
                ],
            g0:    View [ height = 12 ],

            // Guide / Reference. This was a segmented control in every respect
            // except being one: two hand-styled `View`s, so no focus, no tab
            // stop, no keyboard, no press state (register D10). The delivery
            // seam already fit — the pair's value is `app.mode`, deriving from
            // `app.location`, so a pick writes the location and the value comes
            // back round, which is the single source of truth the location
            // comment above asks for.

            modes: Segmented [ width = { parent.width }, height = 30,
                value = { app.mode },
                input(v: object) {
                    app.location = ("" + v) == "guide" ? "guide/" + app.guideAt : "reference/" + app.refAt
                    app.showPage()
                    },

                // each half declares WHERE it goes, so the switch is a link the
                // crawler can follow — without it the reference half of the docs
                // is unreachable from the default location (see SegmentedItem)

                choices = { [ ({ id: "guide",     label: "Guide",     location: "guide/" + app.guideAt }),
                              ({ id: "reference", label: "Reference", location: "reference/" + app.refAt }) ] }
                ],

            // font-size stepper — small / reset / large "A" glyphs zoom every text size

            g_sz:  View [ height = 8 ],
            ctl: View [ width = { parent.width },
                layout: SimpleLayout [ axis = x, spacing = 8 ],
                size: View [ height = 30, cornerRadius = 8, fill = { theme.surface }, stroke = { stroke(1, theme.line) },
                    layout: SimpleLayout [ axis = x, spacing = 0 ],
                    SizeBtn [ glyph = 11, delta = -0.1 ],
                    div1: View [ width = 1, height = 18, y = 6, fill = { theme.line } ],
                    SizeBtn [ glyph = 15, delta = 0 ],
                    div2: View [ width = 1, height = 18, y = 6, fill = { theme.line } ],
                    SizeBtn [ glyph = 19, delta = 0.1 ],
                    width = { this.contentWidth }
                    ],
                mode: Segmented [ height = 30, width = 96, iconSize = 15,
                    value = { app.themeMode },
                    input(v: object) { app.themeMode = "" + v },
                    choices = { [ ({ id: "light",  icon: "SunIcon" }),
                                  ({ id: "system", icon: "AutoIcon" }),
                                  ({ id: "dark",   icon: "MoonIcon" }) ] }
                    ]
                ],

            // guide nav — parts and their chapters

            guideNav: View [ width = { parent.width }, visible = { app.mode == "guide" },
                layout: SimpleLayout [ axis = y, spacing = 2 ],
                PartGroup [ datapath = :guideParts[] ]
                ],

            // reference nav — the component list

            refNav: View [ width = { parent.width }, visible = { app.mode == "reference" },
                layout: SimpleLayout [ axis = y, spacing = 4 ],
                g1:    View [ height = 14 ],
                eyebrow: Mono [ fontSize = 12, letterSpacing = 1.4, fontWeight = semibold, textColor = { theme.textMuted }, text = "COMPONENTS" ],
                g2:    View [ height = 4 ],
                ClassTab [ datapath = :tree[], cname = :name ]
                ]
            ]
        ],

    /* ## The detail pane
       Its own scroller; guide chapters and class pages overlay, the mode +
       selection pick the one live page (so the scroller measures only it).
       `selectable` (prevailing) opts the whole right pane into ordinary
       browser text selection — prose, signatures, Markdown runs — while the
       rail stays chrome. */

    detail: View [ x = { app.railW }, y = 0, width = { app.hostWidth - app.railW }, height = { app.hostHeight }, scrolls = y, selectable = true,
        top: View [ x = 0, y = 0, width = 1, height = 1 ],       // showPage's scroll-to-top anchor
        col: View [ x = 48, y = 40, width = { parent.width - 96 },
            guideCol: View [ width = { parent.width }, visible = { app.mode == "guide" },
                ChapterDetail [ datapath = :guide[], cid = :id ]
                ],
            refCol: View [ width = { parent.width }, visible = { app.mode == "reference" },
                ClassDetail [ datapath = :tree[], cname = :name ]
                ]
            ]
        ]
    ]
